BEGIN;
CREATE SCHEMA erp_purchase_private;
REVOKE ALL ON SCHEMA erp_purchase_private FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE public.erp_purchase_documents(id uuid PRIMARY KEY,cafe_id uuid NOT NULL REFERENCES public.cafes(id),revision integer NOT NULL DEFAULT 1,kind text NOT NULL CHECK(kind IN('request','rfq','quotation','order','invoice')),status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','pending','approved','rejected','converted','posted','cancelled')),number text NOT NULL,title text NOT NULL,supplier_id uuid,source_id uuid,finance_id uuid,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,UNIQUE(cafe_id,id),UNIQUE(cafe_id,kind,number),UNIQUE(cafe_id,finance_id),FOREIGN KEY(cafe_id,supplier_id) REFERENCES public.bf_parties(cafe_id,id),FOREIGN KEY(cafe_id,source_id) REFERENCES public.erp_purchase_documents(cafe_id,id),FOREIGN KEY(cafe_id,finance_id) REFERENCES public.bf_documents(cafe_id,id));
CREATE INDEX erp_purchase_documents_list ON public.erp_purchase_documents(cafe_id,kind,status,created_at DESC);
CREATE TABLE public.erp_purchase_settings(cafe_id uuid PRIMARY KEY REFERENCES public.cafes(id),revision integer NOT NULL DEFAULT 1,payload jsonb NOT NULL);
CREATE TABLE public.erp_purchase_suppliers(cafe_id uuid NOT NULL,id uuid PRIMARY KEY,revision integer NOT NULL DEFAULT 1,payload jsonb NOT NULL,opening_document_id uuid,FOREIGN KEY(cafe_id,id) REFERENCES public.bf_parties(cafe_id,id),FOREIGN KEY(cafe_id,opening_document_id) REFERENCES public.bf_documents(cafe_id,id));
CREATE TABLE public.erp_purchase_receipts(cafe_id uuid NOT NULL,source_document_id uuid PRIMARY KEY,receipt_document_id uuid,status text NOT NULL CHECK(status IN('pending','received')),revision integer NOT NULL DEFAULT 1,FOREIGN KEY(cafe_id,source_document_id) REFERENCES public.bf_documents(cafe_id,id),FOREIGN KEY(cafe_id,receipt_document_id) REFERENCES public.bf_documents(cafe_id,id));
CREATE TABLE public.erp_purchase_credits(id uuid PRIMARY KEY,cafe_id uuid NOT NULL,supplier_id uuid NOT NULL,document_id uuid NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>0),used numeric(18,2) NOT NULL DEFAULT 0 CHECK(used>=0 AND used<=amount),kind text NOT NULL CHECK(kind IN('advance','debit','opening')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(cafe_id,supplier_id) REFERENCES public.bf_parties(cafe_id,id),FOREIGN KEY(cafe_id,document_id) REFERENCES public.bf_documents(cafe_id,id));
CREATE TABLE public.erp_purchase_credit_uses(id uuid PRIMARY KEY,cafe_id uuid NOT NULL,credit_id uuid NOT NULL REFERENCES public.erp_purchase_credits(id),invoice_id uuid NOT NULL,payment_document_id uuid NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>0),FOREIGN KEY(cafe_id,invoice_id) REFERENCES public.bf_documents(cafe_id,id),FOREIGN KEY(cafe_id,payment_document_id) REFERENCES public.bf_documents(cafe_id,id));
CREATE TABLE public.erp_purchase_debits(id uuid PRIMARY KEY,cafe_id uuid NOT NULL,source_document_id uuid NOT NULL,document_id uuid NOT NULL,line_id uuid NOT NULL,net numeric(18,2) NOT NULL CHECK(net>0),tax numeric(18,2) NOT NULL CHECK(tax>=0),cost numeric(18,2) NOT NULL CHECK(cost>=0),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(cafe_id,source_document_id) REFERENCES public.bf_documents(cafe_id,id),FOREIGN KEY(cafe_id,document_id) REFERENCES public.bf_documents(cafe_id,id),FOREIGN KEY(line_id) REFERENCES public.bf_document_lines(id));
CREATE TABLE public.erp_purchase_allocations(id uuid PRIMARY KEY,cafe_id uuid NOT NULL,source_document_id uuid NOT NULL,expense_document_id uuid NOT NULL,posting_document_id uuid NOT NULL,amount numeric(18,2) NOT NULL CHECK(amount>0),payload jsonb NOT NULL,status text NOT NULL DEFAULT 'posted' CHECK(status='posted'),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(cafe_id,source_document_id) REFERENCES public.bf_documents(cafe_id,id),FOREIGN KEY(cafe_id,expense_document_id) REFERENCES public.bf_documents(cafe_id,id),FOREIGN KEY(cafe_id,posting_document_id) REFERENCES public.bf_documents(cafe_id,id));
CREATE INDEX erp_purchase_allocations_source ON public.erp_purchase_allocations(cafe_id,source_document_id);
CREATE INDEX erp_purchase_allocations_expense ON public.erp_purchase_allocations(cafe_id,expense_document_id);
CREATE TABLE public.erp_purchase_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cafe_id uuid NOT NULL REFERENCES public.cafes(id),record_id uuid,action text NOT NULL,payload jsonb NOT NULL,actor uuid NOT NULL,at timestamptz NOT NULL DEFAULT now());
CREATE TABLE erp_purchase_private.requests(cafe_id uuid NOT NULL,request_id uuid NOT NULL,actor uuid NOT NULL,action text NOT NULL,payload jsonb NOT NULL,result jsonb NOT NULL,PRIMARY KEY(cafe_id,request_id));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['erp_purchase_documents','erp_purchase_settings','erp_purchase_suppliers','erp_purchase_receipts','erp_purchase_credits','erp_purchase_credit_uses','erp_purchase_debits','erp_purchase_allocations','erp_purchase_events'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,anon,authenticated,service_role',t);END LOOP;END$$;
DO $$DECLARE ds text[];BEGIN SELECT array_agg(d ORDER BY n) INTO ds FROM(SELECT d,min(n)n FROM unnest(erp_access_private.domains()||ARRAY['purchases']) WITH ORDINALITY x(d,n) GROUP BY d)y;EXECUTE format('CREATE OR REPLACE FUNCTION erp_access_private.domains() RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path='''' AS $f$SELECT %L::text[]$f$',ds);UPDATE public.erp_roles SET permissions=jsonb_build_object('purchases',jsonb_build_object('read',false,'create',false,'update',false,'delete',false,'approve',false,'settings',false,'files',false))||permissions;END$$;
CREATE FUNCTION erp_purchase_private.validate_values(fields jsonb,vals jsonb,p_cafe uuid DEFAULT NULL,p_record uuid DEFAULT NULL,p_kind text DEFAULT NULL,depth integer DEFAULT 0,p_draft boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$
DECLARE f jsonb;v jsonb;t text;x jsonb;txt text;tbl text;col text;valid boolean;metric numeric;BEGIN
 IF coalesce(jsonb_typeof(vals),'')<>'object' OR octet_length(vals::text)>262144 OR depth>2 THEN RAISE EXCEPTION 'بيانات الحقول الإضافية غير صالحة';END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(coalesce(fields,'[]')) LOOP
  t:=f->>'type';IF t IN('static','separator') THEN CONTINUE;END IF;
  v:=coalesce(vals->(f->>'id'),f->'defaultValue');
  IF coalesce((f->>'required')::boolean,false) AND NOT p_draft AND (v IS NULL OR v='null'::jsonb OR v='""'::jsonb OR v='[]'::jsonb OR (t='checkbox' AND v<>'true')) THEN RAISE EXCEPTION 'أكمل الحقل المطلوب: %',f->>'label';END IF;
  IF v IS NULL OR v='null'::jsonb OR v='""'::jsonb THEN CONTINUE;END IF;
  IF t='subform' THEN
   IF jsonb_typeof(v)<>'array' OR jsonb_array_length(v)>100 OR jsonb_array_length(v)<coalesce((f->>'minimumRows')::integer,0) THEN RAISE EXCEPTION 'عدد صفوف النموذج غير صالح';END IF;
   FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP PERFORM erp_purchase_private.validate_values(f->'fields',x,p_cafe,p_record,p_kind,depth+1,p_draft);END LOOP;CONTINUE;
  END IF;
  IF t='location' THEN
   IF jsonb_typeof(v)<>'object' OR jsonb_typeof(v->'latitude')<>'number' OR jsonb_typeof(v->'longitude')<>'number' OR abs((v->>'latitude')::numeric)>90 OR abs((v->>'longitude')::numeric)>180 THEN RAISE EXCEPTION 'إحداثيات الموقع غير صالحة';END IF;CONTINUE;
  END IF;
  IF (t IN('number','currency') AND jsonb_typeof(v)<>'number') OR (t='checkbox' AND jsonb_typeof(v)<>'boolean') OR (t IN('multiselect','multidynamic') AND jsonb_typeof(v)<>'array') OR (t NOT IN('number','currency','checkbox','multiselect','multidynamic') AND jsonb_typeof(v)<>'string') THEN RAISE EXCEPTION 'نوع قيمة الحقل غير صالح';END IF;
  txt:=v#>>'{}';
  IF length(txt)>20000 THEN RAISE EXCEPTION 'قيمة الحقل طويلة';END IF;
  IF (t='select' AND NOT(f->'options' @> jsonb_build_array(v))) OR (t='multiselect' AND NOT(f->'options' @> v)) THEN RAISE EXCEPTION 'اختيارات الحقل غير صالحة';END IF;
  IF t='email' AND txt!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'البريد الإلكتروني غير صالح';END IF;
  IF t='url' AND txt!~'^https?://[^[:space:]]+$' THEN RAISE EXCEPTION 'الرابط غير صالح';END IF;
  IF t='time' AND txt!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN RAISE EXCEPTION 'الوقت غير صالح';END IF;
  IF t='date' THEN IF txt!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'التاريخ غير صالح';END IF;PERFORM txt::date;END IF;
  IF t IN('number','currency','text','textarea','formatted') THEN
   metric:=CASE WHEN t IN('number','currency') THEN txt::numeric ELSE length(txt) END;
   IF metric<nullif(f->>'minimum','')::numeric OR metric>nullif(f->>'maximum','')::numeric THEN RAISE EXCEPTION 'قيمة الحقل خارج الحدود: %',f->>'label';END IF;
  END IF;
  IF t IN('dynamic','multidynamic') THEN
   tbl:=CASE f->>'entity' WHEN 'items' THEN 'bf_items' WHEN 'customers' THEN 'bf_parties' WHEN 'employees' THEN 'bf_staff' WHEN 'warehouses' THEN 'bf_warehouses' WHEN 'accounts' THEN 'bf_accounts' WHEN 'bom' THEN 'erp_mfg_boms' WHEN 'routings' THEN 'erp_mfg_routings' WHEN 'workstations' THEN 'erp_mfg_workstations' WHEN 'orders' THEN 'erp_mfg_orders' WHEN 'sources' THEN 'bf_documents' END;
   IF tbl IS NULL OR p_cafe IS NULL THEN RAISE EXCEPTION 'الكيان المرتبط غير صالح';END IF;col:=CASE WHEN tbl='bf_staff' THEN 'user_id' ELSE 'id' END;
   FOR x IN SELECT value FROM jsonb_array_elements(CASE WHEN t='dynamic' THEN jsonb_build_array(v) ELSE v END) LOOP
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND %I=$2)',tbl,col) INTO valid USING p_cafe,(x#>>'{}')::uuid;
    IF NOT valid THEN RAISE EXCEPTION 'القيمة المرتبطة غير موجودة في العلامة';END IF;
   END LOOP;
  END IF;
  IF t IN('file','image') THEN
   IF p_record IS NULL OR to_regclass('public.erp_files') IS NULL THEN RAISE EXCEPTION 'احفظ السجل وأضف المرفق أولًا';END IF;
   EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.erp_files WHERE cafe_id=$1 AND record_id=$2 AND id=$3 AND entity_type=$4 AND uploaded AND ($5<>''image'' OR mime IN(''image/jpeg'',''image/png'')))' INTO valid USING p_cafe,p_record,txt::uuid,'purchase_document',t;
   IF NOT valid THEN RAISE EXCEPTION 'المرفق غير موجود في هذا السجل';END IF;
  END IF;
  IF coalesce((f->>'unique')::boolean,false) AND depth=0 AND EXISTS(SELECT 1 FROM public.erp_purchase_documents WHERE cafe_id=p_cafe AND kind=p_kind AND id IS DISTINCT FROM p_record AND payload->'customValues'->(f->>'id')=v) THEN RAISE EXCEPTION 'قيمة الحقل مستخدمة مسبقًا: %',f->>'label';END IF;
  END LOOP;
END $$;


CREATE FUNCTION erp_purchase_private.allowed(c uuid,a text) RETURNS boolean LANGUAGE sql STABLE SET search_path='' AS $$SELECT auth.uid() IS NOT NULL AND coalesce(brand_finance_private.role_for(c),'')=ANY(CASE WHEN a='read' THEN ARRAY['owner','manager','accountant','auditor'] WHEN a='settings' THEN ARRAY['owner','manager'] ELSE ARRAY['owner','manager','accountant'] END) AND erp_access_private.allowed(c,'purchases',a)$$;
CREATE FUNCTION erp_purchase_private.authorize(c uuid,a text DEFAULT 'read') RETURNS void LANGUAGE plpgsql SET search_path='' AS $$BEGIN IF NOT erp_purchase_private.allowed(c,a) THEN RAISE EXCEPTION 'صلاحيات المشتريات لا تسمح بهذه العملية' USING ERRCODE='42501';END IF;END$$;
CREATE FUNCTION erp_purchase_private.settings(c uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$SELECT jsonb_build_object('revision',coalesce(s.revision,0),'nextNumber',1,'prefix','PUR-','shareEnabled',false,'showExchangeRate',true,'exchangeMode','manual','exchangeRates','[]'::jsonb,'discountMode','both','updateItemPrices',false,'allowAdjustment',false,'adjustmentLabel','التسوية','adjustmentAccountId',NULL,'defaultPaid',false,'allowDebitNotes',true,'autoApplyCredit',true,'warehouseRequisitions',true,'defaultReceived',true,'excludedItemIds','[]'::jsonb,'excludedCategoryIds','[]'::jsonb,'journalDescription','شراء {number}','taxMode','item','taxRate',15,'statuses','[]'::jsonb,'fields','[]'::jsonb)||coalesce(s.payload,'{}')||jsonb_build_object('revision',coalesce(s.revision,0)) FROM(SELECT 1)x LEFT JOIN public.erp_purchase_settings s ON s.cafe_id=c$$;
CREATE FUNCTION erp_purchase_private.period(c uuid,d date) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$BEGIN PERFORM brand_finance_private.seed(c);IF d IS NULL OR d>(now() AT TIME ZONE 'Asia/Riyadh')::date OR EXISTS(SELECT 1 FROM public.bf_settings WHERE cafe_id=c AND closed_through>=d) THEN RAISE EXCEPTION 'تاريخ العملية غير صالح أو يقع في فترة مغلقة';END IF;END$$;
CREATE FUNCTION erp_purchase_private.balance(c uuid,d uuid) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$BEGIN IF EXISTS(SELECT 1 FROM public.bf_journal WHERE cafe_id=c AND document_id=d HAVING abs(sum(debit-credit))>.001) THEN RAISE EXCEPTION 'القيد المالي غير متوازن';END IF;END$$;
CREATE FUNCTION erp_purchase_private.account(c uuid,code text,label text,kind text) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE aid uuid;BEGIN SELECT id INTO aid FROM public.bf_accounts WHERE cafe_id=c AND bf_accounts.code=account.code;IF aid IS NULL THEN INSERT INTO public.bf_accounts(cafe_id,code,name,kind,active) VALUES(c,code,label,kind,true) RETURNING id INTO aid;END IF;IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=c AND id=aid AND bf_accounts.kind=account.kind AND active AND NOT is_group AND deleted_at IS NULL) THEN RAISE EXCEPTION 'راجع تهيئة الحساب المالي للمشتريات';END IF;RETURN aid;END$$;
CREATE FUNCTION erp_purchase_private.cash(c uuid,a uuid) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$BEGIN IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=c AND id=a AND active AND kind IN('cash','bank') AND NOT coalesce(is_cashier_drawer,false) AND deleted_at IS NULL AND NOT is_group AND NOT frozen) THEN RAISE EXCEPTION 'اختر حسابًا ماليًا نشطًا للمشتريات';END IF;END$$;
CREATE FUNCTION erp_purchase_private.unit_factor(c uuid,item uuid,u text) RETURNS numeric LANGUAGE plpgsql SET search_path='' AS $$DECLARE f numeric;BEGIN IF to_regprocedure('erp_inventory_private.unit_factor(uuid,uuid,text)') IS NOT NULL THEN EXECUTE 'SELECT erp_inventory_private.unit_factor($1,$2,$3)' INTO f USING c,item,u;ELSE SELECT 1 INTO f FROM public.bf_items WHERE cafe_id=c AND id=item AND unit=u;END IF;IF f IS NULL OR f<=0 THEN RAISE EXCEPTION 'وحدة الصنف غير صالحة';END IF;RETURN f;END$$;
CREATE FUNCTION erp_purchase_private.is_stock(c uuid,item uuid) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path='' AS $$DECLARE result boolean:=true;BEGIN IF to_regclass('public.erp_inventory_items') IS NOT NULL THEN EXECUTE 'SELECT kind=''product'' FROM public.erp_inventory_items WHERE cafe_id=$1 AND item_id=$2' INTO result USING c,item;END IF;RETURN coalesce(result,true);END$$;
CREATE FUNCTION erp_purchase_private.warehouse(c uuid,w uuid) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$DECLARE allowed boolean;BEGIN IF to_regprocedure('erp_inventory_private.warehouse_allowed(uuid,uuid,text)') IS NOT NULL THEN EXECUTE 'SELECT erp_inventory_private.warehouse_allowed($1,$2,''write'')' INTO allowed USING c,w;IF NOT coalesce(allowed,false) THEN RAISE EXCEPTION 'لا تملك صلاحية استخدام المستودع' USING ERRCODE='42501';END IF;END IF;END$$;
CREATE FUNCTION erp_purchase_private.item_blocked(c uuid,i uuid,cfg jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path='' AS $$DECLARE blocked boolean:=false;BEGIN IF cfg->'excludedItemIds'?i::text THEN RETURN true;END IF;IF to_regclass('public.erp_inventory_items') IS NOT NULL AND jsonb_array_length(coalesce(cfg->'excludedCategoryIds','[]'))>0 THEN EXECUTE 'WITH RECURSIVE parents AS(SELECT x.id,x.parent_id FROM public.erp_inventory_items i JOIN public.erp_inventory_catalogs x ON x.cafe_id=i.cafe_id AND x.id=i.category_id WHERE i.cafe_id=$1 AND i.item_id=$2 UNION SELECT x.id,x.parent_id FROM public.erp_inventory_catalogs x JOIN parents p ON x.id=p.parent_id WHERE x.cafe_id=$1) SELECT EXISTS(SELECT 1 FROM parents WHERE $3?id::text)' INTO blocked USING c,i,cfg->'excludedCategoryIds';END IF;RETURN blocked;END$$;
CREATE FUNCTION erp_purchase_private.validate(c uuid,p jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$DECLARE cfg jsonb:=erp_purchase_private.settings(c);l jsonb;lines jsonb:='[]';gross numeric;subtotal numeric:=0;discount numeric:=coalesce((p->>'discount')::numeric,0);allocated numeric:=0;share numeric;net numeric;tax numeric;factor numeric;qty numeric;totalnet numeric:=0;totaltax numeric:=0;rate numeric:=(p->>'exchangeRate')::numeric;idx integer:=0;BEGIN
 IF jsonb_typeof(p->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'lines') NOT BETWEEN 1 AND 100 OR length(btrim(p->>'title')) NOT BETWEEN 1 AND 200 OR p->>'kind' NOT IN('request','rfq','quotation','order','invoice') OR p->>'currency'!~'^[A-Z]{3}$' OR rate IS NULL OR rate<=0 OR rate>1e6 OR p->>'currency'='SAR' AND rate<>1 THEN RAISE EXCEPTION 'راجع بيانات مستند المشتريات';END IF;
 IF cfg->>'exchangeMode'='configured' AND p->>'currency'<>'SAR' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'exchangeRates')x WHERE x->>'currency'=p->>'currency' AND(x->>'rate')::numeric=rate) THEN RAISE EXCEPTION 'سعر الصرف لا يطابق السعر المحفوظ';END IF;
 IF p->>'kind' IN('quotation','order','invoice') AND NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=c AND id=(p->>'supplierId')::uuid AND kind='supplier' AND active) THEN RAISE EXCEPTION 'اختر موردًا نشطًا';END IF;
 IF p->>'kind'='rfq' AND(jsonb_array_length(p->'supplierIds')=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p->'supplierIds')x WHERE NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=c AND id=x::uuid AND kind='supplier' AND active))) THEN RAISE EXCEPTION 'حدد موردي طلب عروض الأسعار';END IF;
 IF p->>'kind'='invoice' AND NOT EXISTS(SELECT 1 FROM public.bf_warehouses WHERE cafe_id=c AND id=(p->>'warehouseId')::uuid AND active) THEN RAISE EXCEPTION 'اختر المستودع';END IF;
 FOR l IN SELECT value FROM jsonb_array_elements(p->'lines') LOOP
  qty:=(l->>'quantity')::numeric;IF qty IS NULL OR qty<=0 OR qty>1e6 OR qty<>round(qty,3) OR(l->>'price')::numeric<0 OR(l->>'price')::numeric>1e9 OR(l->>'discount')::numeric<0 OR(l->>'discount')::numeric>1e9 OR(l->>'taxRate')::numeric NOT BETWEEN 0 AND 100 OR NOT EXISTS(SELECT 1 FROM public.bf_items WHERE cafe_id=c AND id=(l->>'itemId')::uuid AND active) OR erp_purchase_private.item_blocked(c,(l->>'itemId')::uuid,cfg) THEN RAISE EXCEPTION 'راجع الأصناف والكميات والأسعار والضريبة';END IF;
  factor:=erp_purchase_private.unit_factor(c,(l->>'itemId')::uuid,l->>'unit');IF qty*factor<>round(qty*factor,3) OR qty*factor>1e6 THEN RAISE EXCEPTION 'الكمية بعد تحويل الوحدة غير صالحة';END IF;
  gross:=round(qty*(l->>'price')::numeric,2);IF l->>'discountType'='percent' AND(l->>'discount')::numeric>100 THEN RAISE EXCEPTION 'نسبة الخصم تتجاوز مئة بالمئة';END IF;gross:=gross-CASE WHEN l->>'discountType'='percent' THEN round(gross*(l->>'discount')::numeric/100,2) ELSE(l->>'discount')::numeric END;IF gross<0 OR cfg->>'discountMode'='invoice' AND(l->>'discount')::numeric<>0 THEN RAISE EXCEPTION 'خصم السطر غير صالح';END IF;subtotal:=subtotal+gross;
 END LOOP;
 IF p->>'discountType'='percent' THEN IF discount>100 THEN RAISE EXCEPTION 'نسبة خصم الفاتورة تتجاوز مئة بالمئة';END IF;discount:=round(subtotal*discount/100,2);END IF;
 IF discount<0 OR discount>subtotal OR discount>1e9 OR cfg->>'discountMode'='line' AND discount<>0 OR (p->>'shipping')::numeric<0 OR(p->>'shipping')::numeric>1e9 OR abs((p->>'adjustment')::numeric)>1e9 OR NOT(cfg->>'allowAdjustment')::boolean AND(p->>'adjustment')::numeric<>0 THEN RAISE EXCEPTION 'الخصم أو التسوية غير صالح';END IF;
 FOR l IN SELECT value FROM jsonb_array_elements(p->'lines') LOOP
  idx:=idx+1;gross:=round((l->>'quantity')::numeric*(l->>'price')::numeric,2);gross:=gross-CASE WHEN l->>'discountType'='percent' THEN round(gross*(l->>'discount')::numeric/100,2) ELSE(l->>'discount')::numeric END;share:=CASE WHEN idx=jsonb_array_length(p->'lines') THEN discount-allocated WHEN subtotal=0 THEN 0 ELSE round(discount*gross/subtotal,2) END;allocated:=allocated+share;gross:=gross-share;
  net:=CASE WHEN(p->>'taxInclusive')::boolean THEN round(gross/(1+(l->>'taxRate')::numeric/100),2) ELSE gross END;tax:=CASE WHEN(p->>'taxInclusive')::boolean THEN gross-net ELSE round(net*(l->>'taxRate')::numeric/100,2) END;
  factor:=erp_purchase_private.unit_factor(c,(l->>'itemId')::uuid,l->>'unit');lines:=lines||jsonb_build_array(l||jsonb_build_object('baseQuantity',(l->>'quantity')::numeric*factor,'factor',factor,'net',round(net*rate,2),'tax',round(tax*rate,2)));totalnet:=totalnet+round(net*rate,2);totaltax:=totaltax+round(tax*rate,2);
 END LOOP;
 IF totalnet+totaltax+round(((p->>'shipping')::numeric+(p->>'adjustment')::numeric)*rate,2)<=0 AND p->>'kind'='invoice' THEN RAISE EXCEPTION 'إجمالي الفاتورة يجب أن يكون موجبًا';END IF;
 RETURN jsonb_build_object('lines',lines,'net',totalnet,'tax',totaltax,'shipping',round((p->>'shipping')::numeric*rate,2),'adjustment',round((p->>'adjustment')::numeric*rate,2),'total',totalnet+totaltax+round((p->>'shipping')::numeric*rate,2)+round((p->>'adjustment')::numeric*rate,2));
END$$;
CREATE FUNCTION erp_purchase_private.apply_credit(c uuid,invoice uuid) RETURNS numeric LANGUAGE plpgsql SET search_path='' AS $$DECLARE d public.bf_documents%ROWTYPE;r public.erp_purchase_credits%ROWTYPE;remaining numeric;credit_amount numeric;pid uuid;used numeric:=0;BEGIN
 SELECT * INTO d FROM public.bf_documents WHERE cafe_id=c AND id=invoice AND kind='purchase' FOR UPDATE;IF d.id IS NULL THEN RAISE EXCEPTION 'فاتورة الشراء غير متاحة';END IF;remaining:=(brand_finance_private.document_state(c,d.id)->>'outstanding')::numeric;
 FOR r IN SELECT x.* FROM public.erp_purchase_credits x WHERE x.cafe_id=c AND x.supplier_id=d.party_id AND x.used<x.amount ORDER BY x.created_at,x.id FOR UPDATE LOOP
  credit_amount:=least(remaining,r.amount-r.used);EXIT WHEN credit_amount<=0;pid:=gen_random_uuid();
  INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,reference_id,total,paid,created_by,note) VALUES(pid,c,'settlement',d.party_id,d.id,credit_amount,credit_amount,auth.uid(),'تطبيق رصيد المورد');
  PERFORM brand_finance_private.line(c,pid,brand_finance_private.account(c,'2000'),credit_amount,0,d.party_id);PERFORM brand_finance_private.line(c,pid,erp_purchase_private.account(c,'1315','دفعات وأرصدة الموردين','receivable'),0,credit_amount,d.party_id);
  INSERT INTO public.erp_purchase_credit_uses(id,cafe_id,credit_id,invoice_id,payment_document_id,amount) VALUES(gen_random_uuid(),c,r.id,d.id,pid,credit_amount);UPDATE public.erp_purchase_credits SET used=erp_purchase_credits.used+credit_amount WHERE id=r.id;remaining:=remaining-credit_amount;used:=used+credit_amount;PERFORM erp_purchase_private.balance(c,pid);
 END LOOP;RETURN used;
END$$;
CREATE FUNCTION erp_purchase_private.post(c uuid,r public.erp_purchase_documents,expected numeric) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$
DECLARE p jsonb:=r.payload;v jsonb;cfg jsonb:=erp_purchase_private.settings(c);l jsonb;doc uuid:=gen_random_uuid();lid uuid;net numeric;tax numeric;total numeric;paid numeric;cost numeric;adjust numeric;remainingadjust numeric;remainingbase numeric;received boolean;aid uuid;inventoryaid uuid;stocked boolean;stocknet numeric:=0;servicenet numeric:=0;BEGIN
 PERFORM brand_finance_private.assert_job_access(c,'brand_finance_execute','purchase');PERFORM erp_purchase_private.period(c,(p->>'date')::date);
 IF r.kind<>'invoice' OR r.status NOT IN('draft','approved') OR r.finance_id IS NOT NULL THEN RAISE EXCEPTION 'الفاتورة مرحّلة أو غير متاحة للإصدار';END IF;
 v:=erp_purchase_private.validate(c,p);PERFORM erp_purchase_private.validate_values(cfg->'fields',coalesce(p->'customValues','{}'),c,r.id,r.kind,0,false);PERFORM erp_purchase_private.warehouse(c,(p->>'warehouseId')::uuid);total:=(v->>'total')::numeric;net:=(v->>'net')::numeric;tax:=(v->>'tax')::numeric;adjust:=(v->>'adjustment')::numeric;
 IF expected IS DISTINCT FROM total THEN RAISE EXCEPTION 'تغير إجمالي الفاتورة راجع الأسعار وسعر الصرف';END IF;
 paid:=round((p->>'paid')::numeric*(p->>'exchangeRate')::numeric,2);IF paid<0 OR paid>total THEN RAISE EXCEPTION 'المبلغ المدفوع يتجاوز إجمالي الفاتورة';END IF;aid:=nullif(p->>'accountId','')::uuid;IF paid>0 THEN PERFORM erp_purchase_private.cash(c,aid);END IF;
 received:=NOT(cfg->>'warehouseRequisitions')::boolean OR(p->>'received')::boolean OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'lines')x WHERE erp_purchase_private.is_stock(c,(x->>'itemId')::uuid));inventoryaid:=CASE WHEN received THEN brand_finance_private.account(c,'1200') ELSE erp_purchase_private.account(c,'1215','مشتريات قيد الاستلام','inventory') END;
 IF adjust<>0 AND NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=c AND id=(p->>'adjustmentAccountId')::uuid AND kind IN('expense','inventory') AND active AND NOT is_group) THEN RAISE EXCEPTION 'اختر حساب تسوية المصروفات أو المخزون';END IF;
 INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,account_id,warehouse_id,subtotal,discount,tax,total,paid,note,created_at,created_by,vat_rate,tax_inclusive)
 VALUES(doc,c,'purchase',r.supplier_id,CASE WHEN paid>0 THEN aid END,(p->>'warehouseId')::uuid,total-tax,0,tax,total,paid,left(replace(replace(coalesce(cfg->>'journalDescription',''),'{number}',r.number),'{supplier}',coalesce((SELECT name FROM public.bf_parties WHERE cafe_id=c AND id=r.supplier_id),''))||CASE WHEN coalesce(p->>'note','')<>'' THEN E'\n'||(p->>'note') ELSE '' END,1000),(p->>'date')::date::timestamp AT TIME ZONE 'Asia/Riyadh',auth.uid(),0,false);
 remainingadjust:=adjust;remainingbase:=net;
 FOR l IN SELECT value FROM jsonb_array_elements(v->'lines') LOOP
  cost:=(l->>'net')::numeric;adjust:=CASE WHEN remainingbase=cost THEN remainingadjust WHEN remainingbase=0 THEN 0 ELSE round(remainingadjust*cost/remainingbase,2) END;remainingbase:=remainingbase-cost;remainingadjust:=remainingadjust-adjust;
  IF cost+adjust<0 THEN RAISE EXCEPTION 'التسوية السالبة تتجاوز قيمة الأصناف';END IF;
  lid:=(l->>'id')::uuid;stocked:=erp_purchase_private.is_stock(c,(l->>'itemId')::uuid);IF stocked THEN stocknet:=stocknet+cost;ELSE servicenet:=servicenet+cost;END IF;
  INSERT INTO public.bf_document_lines(id,cafe_id,document_id,item_id,name,quantity,unit_price,net,tax,cost,unit_label,stock_unit_factor,vat_rate)
  SELECT lid,c,doc,CASE WHEN stocked THEN i.id END,coalesce(nullif(l->>'description',''),i.name),(l->>'baseQuantity')::numeric,round((cost+adjust)/(l->>'baseQuantity')::numeric,6),cost+adjust,(l->>'tax')::numeric,CASE WHEN stocked THEN cost ELSE 0 END,i.unit,1,(l->>'taxRate')::numeric FROM public.bf_items i WHERE cafe_id=c AND id=(l->>'itemId')::uuid;
  IF received AND stocked THEN PERFORM brand_finance_private.stock_move(c,doc,(l->>'itemId')::uuid,(p->>'warehouseId')::uuid,(l->>'baseQuantity')::numeric,cost/(l->>'baseQuantity')::numeric);END IF;
 END LOOP;
 IF(v->>'shipping')::numeric>0 THEN INSERT INTO public.bf_document_lines(cafe_id,document_id,name,quantity,unit_price,net,tax,cost) VALUES(c,doc,'الشحن',1,(v->>'shipping')::numeric,(v->>'shipping')::numeric,0,0);END IF;
 PERFORM brand_finance_private.line(c,doc,inventoryaid,stocknet,0);PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'5100'),servicenet,0);PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'1300'),tax,0);PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'5200'),(v->>'shipping')::numeric,0);
 adjust:=(v->>'adjustment')::numeric;IF adjust<>0 THEN PERFORM brand_finance_private.line(c,doc,(p->>'adjustmentAccountId')::uuid,greatest(adjust,0),greatest(-adjust,0));END IF;
 PERFORM brand_finance_private.line(c,doc,aid,0,paid);PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'2000'),0,total-paid,r.supplier_id);PERFORM erp_purchase_private.balance(c,doc);
 IF paid>0 AND EXISTS(SELECT 1 FROM public.bf_accounts a JOIN public.bf_journal j ON j.account_id=a.id AND j.cafe_id=a.cafe_id WHERE a.cafe_id=c AND a.id=aid AND a.kind='cash' GROUP BY a.id HAVING sum(j.debit-j.credit)<0) THEN RAISE EXCEPTION 'الرصيد النقدي لا يكفي';END IF;
 UPDATE public.erp_purchase_documents SET finance_id=doc,status='posted',revision=revision+1,payload=payload||jsonb_build_object('postedTotals',v) WHERE id=r.id;
 INSERT INTO public.erp_purchase_receipts(cafe_id,source_document_id,receipt_document_id,status) VALUES(c,doc,CASE WHEN received THEN doc END,CASE WHEN received THEN 'received' ELSE 'pending' END);
 IF received AND EXISTS(SELECT 1 FROM public.bf_movements WHERE cafe_id=c AND document_id=doc) AND to_regprocedure('erp_inventory_private.acknowledge_finance(uuid,uuid)') IS NOT NULL THEN EXECUTE 'SELECT erp_inventory_private.acknowledge_finance($1,$2)' USING c,doc;ELSIF NOT received AND to_regprocedure('erp_inventory_private.register_purchase_pending(uuid,uuid)') IS NOT NULL THEN EXECUTE 'SELECT erp_inventory_private.register_purchase_pending($1,$2)' USING c,doc;END IF;
 IF(cfg->>'autoApplyCredit')::boolean THEN PERFORM erp_purchase_private.apply_credit(c,doc);END IF;RETURN doc;
END$$;
CREATE FUNCTION erp_purchase_private.receive(c uuid,invoice uuid,rev integer) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE receipt public.erp_purchase_receipts%ROWTYPE;d public.bf_documents%ROWTYPE;l public.bf_document_lines%ROWTYPE;doc uuid:=gen_random_uuid();amount numeric:=0;cost numeric;BEGIN
 SELECT * INTO receipt FROM public.erp_purchase_receipts WHERE cafe_id=c AND source_document_id=invoice FOR UPDATE;IF receipt.source_document_id IS NULL OR receipt.status<>'pending' OR receipt.revision IS DISTINCT FROM rev THEN RAISE EXCEPTION 'حالة الاستلام تغيرت' USING ERRCODE='40001';END IF;PERFORM erp_purchase_private.period(c,(now() AT TIME ZONE 'Asia/Riyadh')::date);
 SELECT * INTO STRICT d FROM public.bf_documents WHERE cafe_id=c AND id=invoice AND kind='purchase';PERFORM erp_purchase_private.warehouse(c,d.warehouse_id);INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,warehouse_id,reference_id,total,created_by,note) VALUES(doc,c,'stock_adjust',d.party_id,d.warehouse_id,d.id,0,auth.uid(),'استلام فاتورة شراء');
 FOR l IN SELECT * FROM public.bf_document_lines WHERE cafe_id=c AND document_id=d.id AND item_id IS NOT NULL LOOP
  cost:=l.cost-coalesce((SELECT sum(erp_purchase_debits.cost) FROM public.erp_purchase_debits WHERE cafe_id=c AND source_document_id=d.id AND line_id=l.id),0)+coalesce((SELECT sum((x->>'amount')::numeric) FROM public.erp_purchase_allocations a CROSS JOIN LATERAL jsonb_array_elements(a.payload->'lines')x WHERE a.cafe_id=c AND a.source_document_id=d.id AND x->>'lineId'=l.id::text),0);
  IF cost<0 THEN RAISE EXCEPTION 'التسويات تتجاوز تكلفة الصنف قيد الاستلام';END IF;PERFORM brand_finance_private.stock_move(c,doc,l.item_id,d.warehouse_id,l.quantity,cost/l.quantity);amount:=amount+cost;INSERT INTO public.bf_document_lines(cafe_id,document_id,reference_line_id,item_id,name,quantity,unit_price,net,tax,cost) VALUES(c,doc,l.id,l.item_id,l.name,l.quantity,cost/l.quantity,cost,0,cost);
 END LOOP;
 PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'1200'),amount,0);PERFORM brand_finance_private.line(c,doc,erp_purchase_private.account(c,'1215','مشتريات قيد الاستلام','inventory'),0,amount);UPDATE public.erp_purchase_receipts SET status='received',receipt_document_id=doc,revision=revision+1 WHERE source_document_id=invoice;
 IF to_regprocedure('erp_inventory_private.acknowledge_finance(uuid,uuid)') IS NOT NULL THEN EXECUTE 'SELECT erp_inventory_private.acknowledge_finance($1,$2)' USING c,doc;END IF;PERFORM erp_purchase_private.balance(c,doc);RETURN doc;
END$$;
-- Follow a purchase's weighted-average share through issues and warehouse transfers
CREATE FUNCTION erp_purchase_private.cohort(c uuid,invoice uuid,item uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$DECLARE pools jsonb:='{}';shares jsonb:='{}';transfers jsonb:='{}';r record;q numeric;s numeric;part numeric;source uuid;BEGIN
 SELECT coalesce(receipt_document_id,invoice) INTO source FROM public.erp_purchase_receipts WHERE cafe_id=c AND source_document_id=invoice;source:=coalesce(source,invoice);
 FOR r IN SELECT st.warehouse_id,st.quantity-coalesce(sum(m.quantity),0) quantity FROM public.bf_stock st LEFT JOIN public.bf_movements m ON m.cafe_id=st.cafe_id AND m.item_id=st.item_id AND m.warehouse_id=st.warehouse_id WHERE st.cafe_id=c AND st.item_id=item GROUP BY st.warehouse_id,st.quantity LOOP pools:=jsonb_set(pools,ARRAY[r.warehouse_id::text],to_jsonb(r.quantity));END LOOP;
 FOR r IN SELECT m.*,d.kind,d.number FROM public.bf_movements m JOIN public.bf_documents d ON d.cafe_id=m.cafe_id AND d.id=m.document_id WHERE m.cafe_id=c AND m.item_id=item ORDER BY d.number,CASE WHEN m.quantity<0 THEN 0 ELSE 1 END,m.id LOOP
  q:=coalesce((pools->>r.warehouse_id::text)::numeric,0);s:=coalesce((shares->>r.warehouse_id::text)::numeric,0);part:=0;
  IF r.quantity<0 THEN part:=CASE WHEN q>0 THEN least(s,s*least(-r.quantity,q)/q) ELSE 0 END;s:=s-part;IF r.kind='stock_transfer' THEN transfers:=jsonb_set(transfers,ARRAY[r.document_id::text],to_jsonb(coalesce((transfers->>r.document_id::text)::numeric,0)+part));END IF;
  ELSIF r.document_id=source THEN s:=s+least(r.quantity,greatest(0,q+r.quantity));
  ELSIF r.kind='stock_transfer' THEN part:=coalesce((transfers->>r.document_id::text)::numeric,0);s:=s+part*CASE WHEN q<0 THEN greatest(0,q+r.quantity)/r.quantity ELSE 1 END;transfers:=jsonb_set(transfers,ARRAY[r.document_id::text],'0');END IF;
  pools:=jsonb_set(pools,ARRAY[r.warehouse_id::text],to_jsonb(q+r.quantity));shares:=jsonb_set(shares,ARRAY[r.warehouse_id::text],to_jsonb(greatest(s,0)));
 END LOOP;RETURN shares;
END$$;
CREATE FUNCTION erp_purchase_private.value_change(c uuid,doc uuid,invoice uuid,line uuid,amount numeric) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$DECLARE l public.bf_document_lines%ROWTYPE;shares jsonb;r record;totalqty numeric;portion numeric;inventory numeric:=0;result jsonb:='[]';stock public.bf_stock%ROWTYPE;BEGIN
 SELECT * INTO STRICT l FROM public.bf_document_lines WHERE cafe_id=c AND document_id=invoice AND id=line;IF l.item_id IS NULL THEN PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'5100'),greatest(amount,0),greatest(-amount,0));RETURN jsonb_build_object('lineId',line,'inventory',0,'expense',amount);END IF;SELECT sum(quantity) INTO totalqty FROM public.bf_document_lines WHERE cafe_id=c AND document_id=invoice AND item_id=l.item_id;
 IF EXISTS(SELECT 1 FROM public.erp_purchase_receipts WHERE cafe_id=c AND source_document_id=invoice AND status='pending') THEN PERFORM brand_finance_private.line(c,doc,erp_purchase_private.account(c,'1215','مشتريات قيد الاستلام','inventory'),greatest(amount,0),greatest(-amount,0));RETURN jsonb_build_object('lineId',line,'inventory',amount,'cogs',0,'pending',true);END IF;
 shares:=erp_purchase_private.cohort(c,invoice,l.item_id);
 FOR r IN SELECT key::uuid warehouse,value::numeric quantity FROM jsonb_each_text(shares) WHERE value::numeric>0 ORDER BY key LOOP
  SELECT * INTO STRICT stock FROM public.bf_stock WHERE cafe_id=c AND item_id=l.item_id AND warehouse_id=r.warehouse FOR UPDATE;portion:=round(amount*r.quantity/totalqty,2);
  IF NOT coalesce(stock.cost_known,true) OR stock.value+portion<0 THEN RAISE EXCEPTION 'قيمة المخزون غير معروفة أو لا تكفي لتسوية التكلفة';END IF;
  UPDATE public.bf_stock SET value=value+portion,average_cost=CASE WHEN quantity>0 THEN(value+portion)/quantity ELSE 0 END WHERE cafe_id=c AND item_id=l.item_id AND warehouse_id=r.warehouse;
  inventory:=inventory+portion;result:=result||jsonb_build_array(jsonb_build_object('warehouseId',r.warehouse,'quantityShare',r.quantity,'amount',portion));
 END LOOP;
 PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'1200'),greatest(inventory,0),greatest(-inventory,0));PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'5000'),greatest(amount-inventory,0),greatest(inventory-amount,0));RETURN jsonb_build_object('lineId',line,'inventory',inventory,'cogs',amount-inventory,'warehouses',result);
END$$;
ALTER FUNCTION brand_finance_private.refund_lines(uuid,uuid,boolean) RENAME TO refund_lines_before_purchase_debits;
CREATE FUNCTION brand_finance_private.refund_lines(p_cafe uuid,p_doc uuid,p_managed boolean DEFAULT true) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path='' AS $$DECLARE result jsonb:='[]';l jsonb;creditnet numeric;credittax numeric;remaining numeric;net numeric;tax numeric;effective numeric;BEGIN
 FOR l IN SELECT value FROM jsonb_array_elements(brand_finance_private.refund_lines_before_purchase_debits(p_cafe,p_doc,p_managed)) LOOP
  SELECT coalesce(sum(d.net),0),coalesce(sum(d.tax),0) INTO creditnet,credittax FROM public.erp_purchase_debits d WHERE cafe_id=p_cafe AND source_document_id=p_doc AND line_id=(l->>'id')::uuid;
  remaining:=(l->>'quantity')::numeric-(l->>'returned_quantity')::numeric;
  IF remaining>0 AND creditnet>0 THEN net:=greatest(0,(l->>'net')::numeric-(l->>'returned_net')::numeric-creditnet);tax:=greatest(0,(l->>'tax')::numeric-(l->>'returned_tax')::numeric-credittax);effective:=round(net*(l->>'quantity')::numeric/remaining,2);l:=l||jsonb_build_object('net',effective,'returned_net',effective-net);effective:=round(tax*(l->>'quantity')::numeric/remaining,2);l:=l||jsonb_build_object('tax',effective,'returned_tax',effective-tax);END IF;result:=result||jsonb_build_array(l);
 END LOOP;RETURN result;
END$$;
CREATE FUNCTION erp_purchase_private.debit(c uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE original public.bf_documents%ROWTYPE;l jsonb;prepared jsonb:='[]';line public.bf_document_lines%ROWTYPE;returned jsonb;net numeric;tax numeric;totalnet numeric:=0;totaltax numeric:=0;remainingnet numeric;remainingtax numeric;debt numeric;credit numeric;doc uuid:=gen_random_uuid();aid uuid;cost numeric;adjustmentaid uuid;BEGIN
 IF NOT(erp_purchase_private.settings(c)->>'allowDebitNotes')::boolean THEN RAISE EXCEPTION 'الإشعارات المدينة غير مفعلة';END IF;PERFORM erp_purchase_private.period(c,(now() AT TIME ZONE 'Asia/Riyadh')::date);SELECT * INTO original FROM public.bf_documents WHERE cafe_id=c AND id=(p->>'invoiceId')::uuid AND kind='purchase' FOR UPDATE;IF original.id IS NULL THEN RAISE EXCEPTION 'فاتورة الشراء غير متاحة';END IF;
 IF jsonb_array_length(p->'lines') NOT BETWEEN 1 AND 100 OR(SELECT count(DISTINCT x->>'lineId') FROM jsonb_array_elements(p->'lines')x)<>jsonb_array_length(p->'lines') THEN RAISE EXCEPTION 'حدد بنود الإشعار دون تكرار';END IF;
 FOR l IN SELECT value FROM jsonb_array_elements(p->'lines') LOOP
  SELECT * INTO line FROM public.bf_document_lines WHERE cafe_id=c AND document_id=original.id AND id=(l->>'lineId')::uuid;IF line.id IS NULL THEN RAISE EXCEPTION 'بند الفاتورة غير متاح';END IF;SELECT x INTO returned FROM jsonb_array_elements(brand_finance_private.refund_lines(c,original.id,true))x WHERE x->>'id'=line.id::text;remainingnet:=(returned->>'net')::numeric-(returned->>'returned_net')::numeric;remainingtax:=(returned->>'tax')::numeric-(returned->>'returned_tax')::numeric;net:=(l->>'net')::numeric;
  IF net IS NULL OR net<=0 OR net>1e9 OR net<>round(net,2) OR net>remainingnet OR(line.quantity-(returned->>'returned_quantity')::numeric)<=0 THEN RAISE EXCEPTION 'قيمة الإشعار تتجاوز قيمة الكمية المتبقية';END IF;tax:=CASE WHEN net=remainingnet THEN remainingtax ELSE round(remainingtax*net/remainingnet,2) END;
  IF line.item_id IS NULL THEN SELECT(x->>'net')::numeric INTO cost FROM public.erp_purchase_documents r CROSS JOIN LATERAL jsonb_array_elements(r.payload->'postedTotals'->'lines')x WHERE r.cafe_id=c AND r.finance_id=original.id AND x->>'id'=line.id::text;cost:=coalesce(cost,line.net);ELSE cost:=line.cost;END IF;cost:=round(net*cost/line.net,2);prepared:=prepared||jsonb_build_array(jsonb_build_object('lineId',line.id,'net',net,'tax',tax,'cost',cost));totalnet:=totalnet+net;totaltax:=totaltax+tax;
 END LOOP;
 debt:=least(totalnet+totaltax,(brand_finance_private.document_state(c,original.id)->>'outstanding')::numeric);credit:=totalnet+totaltax-debt;aid:=erp_purchase_private.account(c,'1315','دفعات وأرصدة الموردين','receivable');
 INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,reference_id,note,created_by,subtotal,tax,total,paid,account_id) VALUES(doc,c,'refund',original.party_id,original.id,coalesce(p->>'note','إشعار مدين للمورد'),auth.uid(),totalnet,totaltax,totalnet+totaltax,credit,CASE WHEN credit>0 THEN aid END);
 SELECT nullif(payload->>'adjustmentAccountId','')::uuid INTO adjustmentaid FROM public.erp_purchase_documents WHERE cafe_id=c AND finance_id=original.id;adjustmentaid:=coalesce(adjustmentaid,brand_finance_private.account(c,'5200'));
 FOR l IN SELECT value FROM jsonb_array_elements(prepared) LOOP cost:=(l->>'cost')::numeric;net:=(l->>'net')::numeric;PERFORM erp_purchase_private.value_change(c,doc,original.id,(l->>'lineId')::uuid,-cost);PERFORM brand_finance_private.line(c,doc,adjustmentaid,greatest(cost-net,0),greatest(net-cost,0));INSERT INTO public.erp_purchase_debits(id,cafe_id,source_document_id,document_id,line_id,net,tax,cost) VALUES(gen_random_uuid(),c,original.id,doc,(l->>'lineId')::uuid,net,(l->>'tax')::numeric,cost);END LOOP;
 PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'1300'),0,totaltax);PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'2000'),debt,0,original.party_id);PERFORM brand_finance_private.line(c,doc,aid,credit,0,original.party_id);
 IF credit>0 THEN INSERT INTO public.erp_purchase_credits(id,cafe_id,supplier_id,document_id,amount,kind) VALUES(gen_random_uuid(),c,original.party_id,doc,credit,'debit');END IF;PERFORM erp_purchase_private.balance(c,doc);RETURN doc;
END$$;
CREATE FUNCTION erp_purchase_private.allocate(c uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE invoice public.bf_documents%ROWTYPE;expense public.bf_documents%ROWTYPE;amount numeric:=(p->>'amount')::numeric;available numeric;allocated numeric:=0;weight numeric;totalweight numeric;portion numeric;l record;entry jsonb;details jsonb:='[]';doc uuid:=gen_random_uuid();aid uuid;accountleft numeric;reversed boolean;BEGIN
 PERFORM erp_purchase_private.period(c,(now() AT TIME ZONE 'Asia/Riyadh')::date);SELECT * INTO invoice FROM public.bf_documents WHERE cafe_id=c AND id=(p->>'invoiceId')::uuid AND kind='purchase' FOR UPDATE;SELECT * INTO expense FROM public.bf_documents WHERE cafe_id=c AND id=(p->>'expenseId')::uuid AND kind IN('expense','journal') FOR UPDATE;
 IF invoice.id IS NULL OR expense.id IS NULL OR amount IS NULL OR amount<=0 OR amount>1e9 OR amount<>round(amount,2) OR p->>'method' NOT IN('amount','quantity','manual') THEN RAISE EXCEPTION 'اختر فاتورة الشراء ومصدر المصروف وطريقة التوزيع';END IF;
 IF to_regclass('public.bf_gl_drafts') IS NOT NULL THEN EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.bf_gl_drafts WHERE cafe_id=$1 AND document_id=$2 AND reversal_document_id IS NOT NULL)' INTO reversed USING c,expense.id;IF reversed THEN RAISE EXCEPTION 'لا يمكن توزيع مصروف من قيد معكوس';END IF;END IF;
 SELECT coalesce(sum(j.debit-j.credit),0) INTO available FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=c AND j.document_id=expense.id AND a.kind='expense';available:=available-coalesce((SELECT sum(x.amount) FROM public.erp_purchase_allocations x WHERE cafe_id=c AND expense_document_id=expense.id),0);
 IF amount>available THEN RAISE EXCEPTION 'المبلغ يتجاوز المصروف المتاح للتوزيع';END IF;
 SELECT sum(CASE WHEN p->>'method'='quantity' THEN quantity ELSE cost END) INTO totalweight FROM public.bf_document_lines WHERE cafe_id=c AND document_id=invoice.id AND item_id IS NOT NULL;
 IF totalweight IS NULL OR totalweight<=0 THEN RAISE EXCEPTION 'الفاتورة لا تحتوي أصنافًا قابلة لتوزيع التكلفة';END IF;
 IF p->>'method'='manual' AND((SELECT count(DISTINCT x->>'lineId') FROM jsonb_array_elements(p->'lines')x)<>jsonb_array_length(p->'lines') OR(SELECT sum((x->>'amount')::numeric) FROM jsonb_array_elements(p->'lines')x) IS DISTINCT FROM amount OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'lines')x WHERE(x->>'amount')::numeric<0 OR NOT EXISTS(SELECT 1 FROM public.bf_document_lines WHERE cafe_id=c AND document_id=invoice.id AND id=(x->>'lineId')::uuid AND item_id IS NOT NULL))) THEN RAISE EXCEPTION 'مجموع التوزيع اليدوي يجب أن يطابق المصروف';END IF;
 INSERT INTO public.bf_documents(id,cafe_id,kind,reference_id,note,created_by,total) VALUES(doc,c,'journal',invoice.id,'توزيع مصروف على تكلفة المشتريات',auth.uid(),amount);
 FOR l IN SELECT * FROM public.bf_document_lines WHERE cafe_id=c AND document_id=invoice.id AND item_id IS NOT NULL ORDER BY id LOOP
  weight:=CASE WHEN p->>'method'='quantity' THEN l.quantity ELSE l.cost END;
  IF p->>'method'='manual' THEN SELECT coalesce((x->>'amount')::numeric,0) INTO portion FROM jsonb_array_elements(p->'lines')x WHERE x->>'lineId'=l.id::text;portion:=coalesce(portion,0);ELSE portion:=CASE WHEN totalweight=weight THEN amount-allocated ELSE round((amount-allocated)*weight/totalweight,2) END;totalweight:=totalweight-weight;END IF;
  IF portion>0 THEN entry:=erp_purchase_private.value_change(c,doc,invoice.id,l.id,portion);details:=details||jsonb_build_array(entry||jsonb_build_object('amount',portion));allocated:=allocated+portion;END IF;
 END LOOP;
 accountleft:=amount;FOR l IN SELECT j.account_id,sum(j.debit-j.credit) amount FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=c AND j.document_id=expense.id AND a.kind='expense' GROUP BY j.account_id HAVING sum(j.debit-j.credit)>0 ORDER BY j.account_id LOOP
  SELECT coalesce(sum(j.credit-j.debit),0) INTO portion FROM public.bf_journal j JOIN public.erp_purchase_allocations x ON x.cafe_id=j.cafe_id AND x.posting_document_id=j.document_id WHERE x.cafe_id=c AND x.expense_document_id=expense.id AND j.account_id=l.account_id;portion:=least(accountleft,greatest(0,l.amount-portion));PERFORM brand_finance_private.line(c,doc,l.account_id,0,portion);accountleft:=accountleft-portion;EXIT WHEN accountleft=0;
 END LOOP;IF accountleft<>0 OR allocated<>amount THEN RAISE EXCEPTION 'تعذر موازنة توزيع المصروف';END IF;
 INSERT INTO public.erp_purchase_allocations(id,cafe_id,source_document_id,expense_document_id,posting_document_id,amount,payload) VALUES(gen_random_uuid(),c,invoice.id,expense.id,doc,amount,jsonb_build_object('method',p->>'method','lines',details));PERFORM erp_purchase_private.balance(c,doc);RETURN doc;
END$$;
CREATE FUNCTION erp_purchase_private.supplier(c uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE i uuid:=(p->>'id')::uuid;old public.erp_purchase_suppliers%ROWTYPE;opening numeric:=(p->>'openingBalance')::numeric;doc uuid;BEGIN
 SELECT * INTO old FROM public.erp_purchase_suppliers WHERE cafe_id=c AND id=i FOR UPDATE;PERFORM erp_purchase_private.authorize(c,CASE WHEN EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=c AND id=i) THEN 'update' ELSE 'create' END);
 IF coalesce(old.revision,0) IS DISTINCT FROM coalesce((p->>'revision')::integer,0) THEN RAISE EXCEPTION 'بيانات المورد تغيرت' USING ERRCODE='40001';END IF;
 IF length(btrim(p->>'name')) NOT BETWEEN 1 AND 160 OR opening IS NULL OR abs(opening)>1e9 OR opening<>round(opening,2) OR jsonb_typeof(p->'contacts') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'contacts')>30 OR jsonb_array_length(p->'addresses')>30 THEN RAISE EXCEPTION 'راجع بيانات المورد';END IF;
 IF old.opening_document_id IS NOT NULL AND(old.payload->>'openingBalance')::numeric IS DISTINCT FROM opening THEN RAISE EXCEPTION 'الرصيد الافتتاحي المحفوظ يصحح بقيد مالي';END IF;
 IF EXISTS(SELECT 1 FROM public.bf_parties WHERE id=i AND(cafe_id<>c OR kind<>'supplier')) THEN RAISE EXCEPTION 'المورد غير متاح' USING ERRCODE='42501';END IF;
 INSERT INTO public.bf_parties(id,cafe_id,kind,name,phone,email,tax_number,active,details) VALUES(i,c,'supplier',btrim(p->>'name'),p->>'phone',p->>'email',p->>'taxNumber',(p->>'active')::boolean,p-'id'-'revision'-'openingBalance') ON CONFLICT(id) DO UPDATE SET name=excluded.name,phone=excluded.phone,email=excluded.email,tax_number=excluded.tax_number,active=excluded.active,details=bf_parties.details||excluded.details WHERE bf_parties.cafe_id=c AND bf_parties.kind='supplier';
 IF old.opening_document_id IS NULL AND opening<>0 THEN
  IF brand_finance_private.role_for(c)<>'owner' THEN RAISE EXCEPTION 'الرصيد الافتتاحي يتطلب صلاحية المالك' USING ERRCODE='42501';END IF;PERFORM erp_purchase_private.period(c,(p->>'openingDate')::date);doc:=gen_random_uuid();INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,note,created_at,created_by,total) VALUES(doc,c,'opening',i,'رصيد افتتاحي للمورد',(p->>'openingDate')::date::timestamp AT TIME ZONE 'Asia/Riyadh',auth.uid(),abs(opening));
  IF opening>0 THEN PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'3000'),opening,0);PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'2000'),0,opening,i);ELSE PERFORM brand_finance_private.line(c,doc,erp_purchase_private.account(c,'1315','دفعات وأرصدة الموردين','receivable'),-opening,0,i);PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'3000'),0,-opening);INSERT INTO public.erp_purchase_credits(id,cafe_id,supplier_id,document_id,amount,kind) VALUES(gen_random_uuid(),c,i,doc,-opening,'opening');END IF;PERFORM erp_purchase_private.balance(c,doc);
 END IF;
 INSERT INTO public.erp_purchase_suppliers(cafe_id,id,payload,opening_document_id) VALUES(c,i,p-'revision',doc) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,opening_document_id=coalesce(erp_purchase_suppliers.opening_document_id,excluded.opening_document_id),revision=erp_purchase_suppliers.revision+1 WHERE erp_purchase_suppliers.cafe_id=c;RETURN i;
END$$;
CREATE FUNCTION erp_purchase_private.payment(c uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE supplier uuid:=(p->>'supplierId')::uuid;invoice uuid:=nullif(p->>'invoiceId','')::uuid;amount numeric:=(p->>'amount')::numeric;aid uuid:=(p->>'accountId')::uuid;doc uuid:=gen_random_uuid();result jsonb;BEGIN
 PERFORM erp_purchase_private.period(c,(p->>'date')::date);PERFORM erp_purchase_private.cash(c,aid);IF amount IS NULL OR amount<=0 OR amount>1e9 OR amount<>round(amount,2) OR NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=c AND id=supplier AND kind='supplier' AND active) THEN RAISE EXCEPTION 'راجع المورد والمبلغ';END IF;
 IF invoice IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=c AND id=invoice AND party_id=supplier AND kind='purchase') THEN RAISE EXCEPTION 'الفاتورة لا تخص المورد';END IF;result:=public.brand_finance_execute(c,'settlement',jsonb_build_object('documentId',invoice,'accountId',aid,'amount',amount,'note',p->>'note'),gen_random_uuid());RETURN(result->>'id')::uuid;END IF;
 INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,account_id,note,created_by,total,paid,created_at) VALUES(doc,c,'journal',supplier,aid,coalesce(p->>'note','دفعة مقدمة للمورد'),auth.uid(),amount,amount,(p->>'date')::date::timestamp AT TIME ZONE 'Asia/Riyadh');
 PERFORM brand_finance_private.line(c,doc,erp_purchase_private.account(c,'1315','دفعات وأرصدة الموردين','receivable'),amount,0,supplier);PERFORM brand_finance_private.line(c,doc,aid,0,amount);IF EXISTS(SELECT 1 FROM public.bf_accounts a JOIN public.bf_journal j ON j.account_id=a.id AND j.cafe_id=a.cafe_id WHERE a.cafe_id=c AND a.id=aid AND a.kind='cash' GROUP BY a.id HAVING sum(j.debit-j.credit)<0) THEN RAISE EXCEPTION 'الرصيد النقدي لا يكفي';END IF;
 INSERT INTO public.erp_purchase_credits(id,cafe_id,supplier_id,document_id,amount,kind) VALUES(gen_random_uuid(),c,supplier,doc,amount,'advance');PERFORM erp_purchase_private.balance(c,doc);RETURN doc;
END$$;
CREATE FUNCTION erp_purchase_private.save(c uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$DECLARE r public.erp_purchase_documents%ROWTYPE;i uuid:=(p->>'id')::uuid;cfg jsonb:=erp_purchase_private.settings(c);n text:=btrim(coalesce(p->>'number',''));sid uuid:=nullif(p->>'sourceId','')::uuid;source public.erp_purchase_documents%ROWTYPE;BEGIN
 p:=jsonb_set(p-'postedTotals','{customValues}',erp_manufacturing_private.custom_defaults(cfg->'fields',coalesce(p->'customValues','{}')));
 SELECT * INTO r FROM public.erp_purchase_documents WHERE cafe_id=c AND id=i FOR UPDATE;PERFORM erp_purchase_private.authorize(c,CASE WHEN r.id IS NULL THEN 'create' ELSE 'update' END);
 IF coalesce(r.revision,0) IS DISTINCT FROM coalesce((p->>'revision')::integer,0) THEN RAISE EXCEPTION 'المستند تغير أعد تحميله' USING ERRCODE='40001';END IF;IF r.id IS NOT NULL AND(r.status NOT IN('draft','rejected') OR r.kind<>p->>'kind') THEN RAISE EXCEPTION 'المستند معتمد أو مرتبط بعملية لاحقة ولا يقبل التعديل';END IF;
 PERFORM erp_purchase_private.validate(c,p);PERFORM erp_purchase_private.validate_values(cfg->'fields',coalesce(p->'customValues','{}'),c,i,p->>'kind',0,true);IF(SELECT count(DISTINCT l->>'id') FROM jsonb_array_elements(p->'lines')l)<>jsonb_array_length(p->'lines') THEN RAISE EXCEPTION 'لا تكرر معرف السطر';END IF;
 IF sid IS NOT NULL THEN SELECT * INTO source FROM public.erp_purchase_documents WHERE cafe_id=c AND id=sid;IF source.id IS NULL OR source.status NOT IN('approved','converted') OR r.id IS NOT NULL AND sid IS DISTINCT FROM r.source_id THEN RAISE EXCEPTION 'المستند المصدر غير متاح';END IF;END IF;
 IF n='' THEN n:=coalesce(cfg->>'prefix','PUR-')||(cfg->>'nextNumber');INSERT INTO public.erp_purchase_settings(cafe_id,payload) VALUES(c,cfg||jsonb_build_object('nextNumber',(cfg->>'nextNumber')::integer+1)) ON CONFLICT(cafe_id) DO UPDATE SET payload=excluded.payload,revision=erp_purchase_settings.revision+1;END IF;
 INSERT INTO public.erp_purchase_documents(id,cafe_id,kind,number,title,supplier_id,source_id,payload,created_by) VALUES(i,c,p->>'kind',n,p->>'title',nullif(p->>'supplierId','')::uuid,sid,(p-'revision')||jsonb_build_object('number',n),auth.uid()) ON CONFLICT(id) DO UPDATE SET number=excluded.number,title=excluded.title,supplier_id=excluded.supplier_id,payload=excluded.payload,status='draft',revision=erp_purchase_documents.revision+1 WHERE erp_purchase_documents.cafe_id=c;
 IF NOT FOUND THEN RAISE EXCEPTION 'المستند غير متاح' USING ERRCODE='42501';END IF;RETURN i;
END$$;
CREATE FUNCTION erp_purchase_private.service_return(c uuid,refund uuid) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$DECLARE amount numeric;BEGIN
 SELECT coalesce(sum(l.net),0) INTO amount FROM public.bf_document_lines l JOIN public.bf_document_lines original ON original.cafe_id=l.cafe_id AND original.id=l.reference_line_id JOIN public.erp_purchase_documents r ON r.cafe_id=original.cafe_id AND r.finance_id=original.document_id WHERE l.cafe_id=c AND l.document_id=refund AND l.item_id IS NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(r.payload->'lines')x WHERE x->>'id'=original.id::text);
 PERFORM brand_finance_private.line(c,refund,brand_finance_private.account(c,'5200'),amount,0);PERFORM brand_finance_private.line(c,refund,brand_finance_private.account(c,'5100'),0,amount);
END$$;
ALTER FUNCTION brand_finance_private.post_refund(uuid,jsonb,uuid) RENAME TO post_refund_before_purchase_services;
CREATE FUNCTION brand_finance_private.post_refund(p_cafe uuid,p_payload jsonb,p_id uuid) RETURNS bigint LANGUAGE plpgsql SET search_path='' AS $$DECLARE number bigint;BEGIN IF EXISTS(SELECT 1 FROM public.erp_purchase_documents WHERE cafe_id=p_cafe AND finance_id=(p_payload->>'documentId')::uuid) THEN PERFORM erp_purchase_private.authorize(p_cafe,'approve');END IF;IF EXISTS(SELECT 1 FROM public.erp_purchase_receipts WHERE cafe_id=p_cafe AND source_document_id=(p_payload->>'documentId')::uuid AND status='pending') THEN RAISE EXCEPTION 'استلم البضاعة قبل تسجيل مرتجع مخزني';END IF;number:=brand_finance_private.post_refund_before_purchase_services(p_cafe,p_payload,p_id);IF EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=p_cafe AND id=(p_payload->>'documentId')::uuid AND kind='purchase') THEN PERFORM erp_purchase_private.service_return(p_cafe,p_id);END IF;RETURN number;END$$;
CREATE FUNCTION erp_purchase_private.copy_values(fields jsonb,vals jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$DECLARE f jsonb;result jsonb:=coalesce(vals,'{}');rows jsonb;BEGIN FOR f IN SELECT value FROM jsonb_array_elements(coalesce(fields,'[]')) LOOP IF f->>'type' IN('file','image') OR coalesce((f->>'unique')::boolean,false) THEN result:=jsonb_set(result,ARRAY[f->>'id'],'""');ELSIF f->>'type'='subform' AND jsonb_typeof(result->(f->>'id'))='array' THEN SELECT coalesce(jsonb_agg(erp_purchase_private.copy_values(f->'fields',x)),'[]') INTO rows FROM jsonb_array_elements(result->(f->>'id'))x;result:=jsonb_set(result,ARRAY[f->>'id'],rows);END IF;END LOOP;RETURN result;END$$;

CREATE FUNCTION public.erp_purchases_write(p_cafe_id uuid,p_action text,p_payload jsonb,p_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE c uuid:=p_cafe_id;p jsonb:=p_payload;r public.erp_purchase_documents%ROWTYPE;existing erp_purchase_private.requests%ROWTYPE;rid uuid;result jsonb;cfg jsonb;nextkind text;lines jsonb;row jsonb;sid uuid;BEGIN
 PERFORM erp_purchase_private.authorize(c,'read');IF p_request_id IS NULL OR jsonb_typeof(p) IS DISTINCT FROM 'object' OR octet_length(p::text)>500000 THEN RAISE EXCEPTION 'طلب المشتريات غير صالح';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(c::text,60412));SELECT * INTO existing FROM erp_purchase_private.requests WHERE cafe_id=c AND request_id=p_request_id;
 IF existing.request_id IS NOT NULL THEN IF existing.actor<>auth.uid() OR existing.action<>p_action OR existing.payload<>p THEN RAISE EXCEPTION 'معرف الطلب مستخدم لعملية أخرى';END IF;RETURN existing.result;END IF;
 IF p_action='save' THEN IF coalesce((p->>'revision')::integer,0)=0 AND nullif(p->>'sourceId','') IS NOT NULL THEN RAISE EXCEPTION 'أنشئ المستند المرتبط من إجراء التحويل';END IF;rid:=erp_purchase_private.save(c,p);
 ELSIF p_action='supplier' THEN rid:=erp_purchase_private.supplier(c,p);
 ELSIF p_action='delete_supplier' THEN
  PERFORM erp_purchase_private.authorize(c,'delete');rid:=(p->>'id')::uuid;IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=c AND id=rid AND kind='supplier') THEN RAISE EXCEPTION 'المورد غير متاح' USING ERRCODE='42501';END IF;
  IF coalesce((SELECT revision FROM public.erp_purchase_suppliers WHERE cafe_id=c AND id=rid),0) IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'المورد تغير' USING ERRCODE='40001';END IF;
  IF EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=c AND party_id=rid) OR EXISTS(SELECT 1 FROM public.erp_purchase_documents WHERE cafe_id=c AND(supplier_id=rid OR payload->'supplierIds'?rid::text)) THEN RAISE EXCEPTION 'المورد مرتبط بمعاملات ويمكن إيقافه بدل حذفه';END IF;
  DELETE FROM public.erp_purchase_suppliers WHERE cafe_id=c AND id=rid;DELETE FROM public.bf_parties WHERE cafe_id=c AND id=rid;
 ELSIF p_action='import_suppliers' THEN IF jsonb_array_length(p->'rows') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'حدد من مورد واحد إلى مئة مورد';END IF;FOR row IN SELECT value FROM jsonb_array_elements(p->'rows') LOOP PERFORM erp_purchase_private.supplier(c,row);END LOOP;result:=jsonb_build_object('count',jsonb_array_length(p->'rows'));
 ELSIF p_action='settings' THEN
  PERFORM erp_purchase_private.authorize(c,'settings');cfg:=erp_purchase_private.settings(c);IF(cfg->>'revision')::integer IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'الإعدادات تغيرت' USING ERRCODE='40001';END IF;
  IF jsonb_typeof(p) IS DISTINCT FROM 'object'
   OR EXISTS(SELECT 1 FROM unnest(ARRAY['revision','nextNumber','taxRate'])k WHERE jsonb_typeof(p->k) IS DISTINCT FROM 'number')
   OR EXISTS(SELECT 1 FROM unnest(ARRAY['prefix','exchangeMode','discountMode','adjustmentLabel','journalDescription','taxMode'])k WHERE jsonb_typeof(p->k) IS DISTINCT FROM 'string')
   OR EXISTS(SELECT 1 FROM unnest(ARRAY['shareEnabled','showExchangeRate','updateItemPrices','allowAdjustment','defaultPaid','allowDebitNotes','autoApplyCredit','warehouseRequisitions','defaultReceived'])k WHERE jsonb_typeof(p->k) IS DISTINCT FROM 'boolean')
   OR EXISTS(SELECT 1 FROM unnest(ARRAY['exchangeRates','statuses','fields','excludedItemIds','excludedCategoryIds'])k WHERE jsonb_typeof(p->k) IS DISTINCT FROM 'array')
   OR NOT(p?'adjustmentAccountId') OR coalesce(jsonb_typeof(p->'adjustmentAccountId'),'') NOT IN('null','string')
  THEN RAISE EXCEPTION 'أكمل إعدادات المشتريات بالقيم الصحيحة';END IF;
  IF(p->>'nextNumber')::numeric NOT BETWEEN 1 AND 2147483646 OR trunc((p->>'nextNumber')::numeric)<>(p->>'nextNumber')::numeric
   OR length(p->>'prefix')>30 OR length(p->>'adjustmentLabel')>80 OR length(p->>'journalDescription')>1000
   OR coalesce(p->>'discountMode','') NOT IN('invoice','line','both') OR coalesce(p->>'exchangeMode','') NOT IN('manual','configured') OR coalesce(p->>'taxMode','') NOT IN('item','none','specific')
   OR(p->>'taxRate')::numeric NOT BETWEEN 0 AND 100 OR jsonb_array_length(p->'statuses')>100 OR jsonb_array_length(p->'exchangeRates')>100 OR jsonb_array_length(p->'excludedItemIds')>1000 OR jsonb_array_length(p->'excludedCategoryIds')>1000
  THEN RAISE EXCEPTION 'راجع إعدادات المشتريات';END IF;
  FOR row IN SELECT value FROM jsonb_array_elements(p->'exchangeRates') LOOP
   IF jsonb_typeof(row) IS DISTINCT FROM 'object' OR jsonb_typeof(row->'currency') IS DISTINCT FROM 'string' OR coalesce(row->>'currency','')!~'^[A-Z]{3}$' OR jsonb_typeof(row->'rate') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'راجع أسعار العملات';END IF;
   IF(row->>'rate')::numeric<=0 OR(row->>'rate')::numeric>1000000 THEN RAISE EXCEPTION 'راجع أسعار العملات';END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'exchangeRates')x GROUP BY x->>'currency' HAVING count(*)>1) THEN RAISE EXCEPTION 'عملة مكررة في أسعار الصرف';END IF;
  FOR row IN SELECT value FROM jsonb_array_elements(p->'statuses') LOOP
   IF jsonb_typeof(row) IS DISTINCT FROM 'object' OR jsonb_typeof(row->'id') IS DISTINCT FROM 'string' OR jsonb_typeof(row->'name') IS DISTINCT FROM 'string' OR length(btrim(coalesce(row->>'id',''))) NOT BETWEEN 1 AND 80 OR length(btrim(coalesce(row->>'name',''))) NOT BETWEEN 1 AND 100 OR coalesce(row->>'kind','') NOT IN('request','rfq','quotation','order','invoice') THEN RAISE EXCEPTION 'راجع حالات المشتريات';END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'statuses')x GROUP BY x->>'id' HAVING count(*)>1) THEN RAISE EXCEPTION 'معرف حالة مكرر';END IF;
  FOR row IN SELECT value FROM jsonb_array_elements((p->'excludedItemIds')||(p->'excludedCategoryIds')) LOOP
   IF jsonb_typeof(row) IS DISTINCT FROM 'string' OR(row#>>'{}')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'راجع الأصناف والمجموعات المستبعدة';END IF;
  END LOOP;
  IF jsonb_typeof(p->'adjustmentAccountId')='string' AND NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=c AND id=(p->>'adjustmentAccountId')::uuid AND active AND NOT coalesce(is_group,false) AND deleted_at IS NULL) THEN RAISE EXCEPTION 'حساب التسوية غير متاح';END IF;
  PERFORM erp_manufacturing_private.validate_custom_fields(p->'fields');
  INSERT INTO public.erp_purchase_settings(cafe_id,payload) VALUES(c,p-'revision') ON CONFLICT(cafe_id) DO UPDATE SET payload=excluded.payload,revision=erp_purchase_settings.revision+1;
 ELSIF p_action IN('payment','return','debit','allocate','receive','apply_credit') THEN
  PERFORM erp_purchase_private.authorize(c,'approve');PERFORM brand_finance_private.assert_job_access(c,'brand_finance_execute',CASE WHEN p_action='return' THEN 'refund' WHEN p_action='payment' THEN 'settlement' ELSE 'purchase' END);
  IF p_action='apply_credit' THEN PERFORM erp_purchase_private.period(c,(now() AT TIME ZONE 'Asia/Riyadh')::date);rid:=(p->>'id')::uuid;PERFORM erp_purchase_private.apply_credit(c,rid);ELSIF p_action='payment' THEN rid:=erp_purchase_private.payment(c,p);ELSIF p_action='debit' THEN rid:=erp_purchase_private.debit(c,p);ELSIF p_action='allocate' THEN rid:=erp_purchase_private.allocate(c,p);ELSIF p_action='receive' THEN rid:=erp_purchase_private.receive(c,(p->>'id')::uuid,(p->>'revision')::integer);
  ELSE IF NOT EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=c AND id=(p->>'invoiceId')::uuid AND kind='purchase') OR EXISTS(SELECT 1 FROM public.erp_purchase_receipts WHERE cafe_id=c AND source_document_id=(p->>'invoiceId')::uuid AND status='pending') THEN RAISE EXCEPTION 'استلم البضاعة قبل تسجيل مرتجع مخزني';END IF;
   result:=public.brand_finance_execute(c,'refund',(p-'invoiceId')||jsonb_build_object('documentId',p->>'invoiceId'),gen_random_uuid());rid:=(result->>'id')::uuid;
  END IF;
 ELSE
  SELECT * INTO r FROM public.erp_purchase_documents WHERE cafe_id=c AND id=(p->>'id')::uuid FOR UPDATE;IF r.id IS NULL THEN RAISE EXCEPTION 'المستند غير متاح' USING ERRCODE='42501';END IF;IF r.revision IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'المستند تغير' USING ERRCODE='40001';END IF;rid:=r.id;
  IF p_action='note' THEN PERFORM erp_purchase_private.authorize(c,'update');IF length(btrim(coalesce(p->>'note',''))) NOT BETWEEN 1 AND 5000 THEN RAISE EXCEPTION 'أدخل الملاحظة';END IF;UPDATE public.erp_purchase_documents SET revision=revision+1 WHERE id=r.id;result:=jsonb_build_object('id',r.id,'note',p->>'note');
  ELSIF p_action='delete' THEN PERFORM erp_purchase_private.authorize(c,'delete');IF r.status NOT IN('draft','rejected') THEN RAISE EXCEPTION 'لا يمكن حذف مستند معتمد';END IF;DELETE FROM public.erp_purchase_documents WHERE id=r.id;
  ELSIF p_action='copy' THEN PERFORM erp_purchase_private.authorize(c,'create');SELECT jsonb_agg(l||jsonb_build_object('id',gen_random_uuid())) INTO lines FROM jsonb_array_elements(r.payload->'lines')l;rid:=erp_purchase_private.save(c,r.payload||jsonb_build_object('customValues',erp_purchase_private.copy_values(erp_purchase_private.settings(c)->'fields',r.payload->'customValues'),'id',gen_random_uuid(),'revision',0,'number','','sourceId',NULL,'lines',lines,'paid',0));
  ELSIF p_action='convert' THEN
   PERFORM erp_purchase_private.authorize(c,'approve');PERFORM erp_purchase_private.authorize(c,'create');nextkind:=p->>'kind';IF r.status<>'approved' OR NOT(r.kind='request' AND nextkind IN('rfq','order') OR r.kind='rfq' AND nextkind='quotation' OR r.kind='quotation' AND nextkind='order' OR r.kind='order' AND nextkind='invoice') THEN RAISE EXCEPTION 'اعتمد المستند وحدد التحويل التالي في دورة الشراء';END IF;
   sid:=coalesce(nullif(p->>'supplierId','')::uuid,r.supplier_id);IF r.kind='rfq' AND NOT(r.payload->'supplierIds'?sid::text) THEN RAISE EXCEPTION 'المورد غير مدعو إلى طلب العرض';END IF;SELECT jsonb_agg(l||jsonb_build_object('id',gen_random_uuid())) INTO lines FROM jsonb_array_elements(r.payload->'lines')l;
   rid:=erp_purchase_private.save(c,r.payload||jsonb_build_object('customValues',erp_purchase_private.copy_values(erp_purchase_private.settings(c)->'fields',r.payload->'customValues'),'id',gen_random_uuid(),'revision',0,'kind',nextkind,'number','','sourceId',r.id,'supplierId',sid,'supplierIds',CASE WHEN nextkind='rfq' AND coalesce(jsonb_array_length(p->'supplierIds'),0)>0 THEN p->'supplierIds' ELSE r.payload->'supplierIds' END,'lines',lines,'paid',0));
   IF r.kind<>'rfq' THEN UPDATE public.erp_purchase_documents SET status='converted',revision=revision+1 WHERE id=r.id;ELSE IF EXISTS(SELECT 1 FROM public.erp_purchase_documents WHERE cafe_id=c AND source_id=r.id AND supplier_id=sid AND id<>rid AND status<>'cancelled') THEN RAISE EXCEPTION 'تم إنشاء عرض لهذا المورد من الطلب نفسه';END IF;END IF;
  ELSIF p_action='post' THEN PERFORM erp_purchase_private.authorize(c,'approve');rid:=erp_purchase_private.post(c,r,(p->>'expectedTotal')::numeric);result:=jsonb_build_object('id',r.id,'financeId',rid);
  ELSIF p_action IN('submit','approve','reject','cancel') THEN
   PERFORM erp_purchase_private.authorize(c,CASE WHEN p_action='submit' THEN 'update' ELSE 'approve' END);
   IF NOT(p_action='submit' AND r.status IN('draft','rejected') OR p_action IN('approve','reject') AND r.status='pending' OR p_action='cancel' AND r.status IN('draft','pending','approved','rejected') AND NOT EXISTS(SELECT 1 FROM public.erp_purchase_documents WHERE cafe_id=c AND source_id=r.id AND status<>'cancelled')) THEN RAISE EXCEPTION 'الانتقال غير متاح في الحالة الحالية';END IF;
   IF p_action='approve' THEN PERFORM erp_purchase_private.validate_values(erp_purchase_private.settings(c)->'fields',coalesce(r.payload->'customValues','{}'),c,r.id,r.kind,0,false);END IF;
   UPDATE public.erp_purchase_documents SET status=CASE p_action WHEN 'submit' THEN 'pending' WHEN 'approve' THEN 'approved' WHEN 'reject' THEN 'rejected' ELSE 'cancelled' END,revision=revision+1 WHERE id=r.id;
  ELSE RAISE EXCEPTION 'عملية المشتريات غير معروفة';END IF;
 END IF;
 IF p_action IN('delete','cancel') AND r.source_id IS NOT NULL THEN UPDATE public.erp_purchase_documents source SET status='approved',revision=revision+1 WHERE source.cafe_id=c AND source.id=r.source_id AND source.status='converted' AND NOT EXISTS(SELECT 1 FROM public.erp_purchase_documents child WHERE child.cafe_id=c AND child.source_id=source.id AND child.status<>'cancelled');END IF;
 result:=coalesce(result,jsonb_build_object('id',rid));INSERT INTO public.erp_purchase_events(cafe_id,record_id,action,payload,actor) VALUES(c,rid,p_action,result,auth.uid());INSERT INTO erp_purchase_private.requests(cafe_id,request_id,actor,action,payload,result) VALUES(c,p_request_id,auth.uid(),p_action,p,result);RETURN result;
END$$;
CREATE FUNCTION erp_purchase_private.invoice_lines(c uuid,i uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$SELECT coalesce(jsonb_agg(original||jsonb_build_object('refund_net',adjusted->'net','refund_tax',adjusted->'tax','refund_returned_net',adjusted->'returned_net','refund_returned_tax',adjusted->'returned_tax')),'[]') FROM jsonb_array_elements(brand_finance_private.refund_lines_before_purchase_debits(c,i,true))original JOIN jsonb_array_elements(brand_finance_private.refund_lines(c,i,true))adjusted ON adjusted->>'id'=original->>'id'$$;
CREATE FUNCTION public.erp_purchases_read(p_cafe_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE c uuid:=p_cafe_id;centers jsonb:='[]';defaults jsonb:='{}';categories jsonb:='[]';inventorydocs jsonb:='[]';units jsonb;BEGIN
 PERFORM erp_purchase_private.authorize(c);IF to_regclass('public.erp_cost_centers') IS NOT NULL THEN EXECUTE 'SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''name'',name)),''[]'') FROM public.erp_cost_centers WHERE cafe_id=$1 AND active AND NOT is_group' INTO centers USING c;END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('itemId',id,'name',unit,'factor',1)),'[]') INTO units FROM public.bf_items WHERE cafe_id=c;
 IF to_regclass('public.erp_inventory_items') IS NOT NULL THEN EXECUTE 'SELECT $2||coalesce(jsonb_agg(jsonb_build_object(''itemId'',i.item_id,''name'',u->>''name'',''factor'',u->''factor'')),''[]'') FROM public.erp_inventory_items i JOIN public.erp_inventory_catalogs cat ON cat.cafe_id=i.cafe_id AND cat.id=i.unit_template_id CROSS JOIN LATERAL jsonb_array_elements(cat.payload->''units'')u WHERE i.cafe_id=$1' INTO units USING c,units;END IF;
 IF to_regclass('public.erp_inventory_items') IS NOT NULL THEN EXECUTE 'SELECT coalesce(jsonb_object_agg(item_id,payload),''{}'') FROM public.erp_inventory_items WHERE cafe_id=$1' INTO defaults USING c;END IF;
 IF to_regclass('public.erp_inventory_catalogs') IS NOT NULL THEN EXECUTE 'SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''name'',name)),''[]'') FROM public.erp_inventory_catalogs WHERE cafe_id=$1 AND kind=''category'' AND active' INTO categories USING c;END IF;
 IF to_regclass('public.erp_inventory_documents') IS NOT NULL THEN EXECUTE 'SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',i.id,''invoiceId'',d.id,''code'',i.code,''status'',i.status)),''[]'') FROM public.erp_inventory_documents i JOIN public.bf_documents d ON d.cafe_id=i.cafe_id AND d.id::text=i.payload->>''sourceInvoiceId'' AND d.kind=''purchase'' WHERE i.cafe_id=$1 AND i.source_mode=''financial''' INTO inventorydocs USING c;END IF;
 RETURN jsonb_build_object('records',coalesce((SELECT jsonb_agg(d.payload||jsonb_build_object('id',d.id,'revision',d.revision,'status',d.status,'financeId',d.finance_id,'createdAt',d.created_at,'total',coalesce((d.payload->'postedTotals'->>'total')::numeric,0)) ORDER BY d.created_at DESC) FROM public.erp_purchase_documents d WHERE cafe_id=c),'[]'),
 'suppliers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',b.id,'revision',coalesce(s.revision,0),'name',b.name,'phone',b.phone,'email',b.email,'taxNumber',b.tax_number,'active',b.active,'firstName','','lastName','','mobile','','commercialRegistration','','number','','currency','SAR','address',jsonb_build_object('building','','street','','additional','','district','','city','','postal','','short','','country','SA'),'contacts','[]'::jsonb,'addresses','[]'::jsonb,'note','','openingBalance',0,'openingDate',current_date)||coalesce(s.payload,'{}')||jsonb_build_object('revision',coalesce(s.revision,0),'name',b.name,'active',b.active) ORDER BY b.name) FROM public.bf_parties b LEFT JOIN public.erp_purchase_suppliers s ON s.cafe_id=b.cafe_id AND s.id=b.id WHERE b.cafe_id=c AND b.kind='supplier'),'[]'),
 'invoices',coalesce((SELECT jsonb_agg(to_jsonb(d)-'cafe_id'||brand_finance_private.document_state(c,d.id)||jsonb_build_object('lines',CASE WHEN d.kind='purchase' THEN erp_purchase_private.invoice_lines(c,d.id) ELSE coalesce((SELECT jsonb_agg(to_jsonb(l)-'cafe_id'-'document_id') FROM public.bf_document_lines l WHERE cafe_id=c AND document_id=d.id),'[]') END,'debit',EXISTS(SELECT 1 FROM public.erp_purchase_debits WHERE cafe_id=c AND document_id=d.id)) ORDER BY d.number DESC) FROM public.bf_documents d WHERE cafe_id=c AND(d.kind='purchase' OR d.kind='refund' AND EXISTS(SELECT 1 FROM public.bf_documents src WHERE src.cafe_id=c AND src.id=d.reference_id AND src.kind='purchase'))),'[]'),
 'payments',coalesce((SELECT jsonb_agg(to_jsonb(d)-'cafe_id' ORDER BY d.number DESC) FROM public.bf_documents d JOIN public.bf_parties b ON b.cafe_id=d.cafe_id AND b.id=d.party_id WHERE d.cafe_id=c AND b.kind='supplier' AND(d.kind='settlement' OR EXISTS(SELECT 1 FROM public.erp_purchase_credits WHERE cafe_id=c AND document_id=d.id))),'[]'),
 'credits',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'supplierId',supplier_id,'amount',amount,'used',used,'kind',kind,'date',created_at)) FROM public.erp_purchase_credits WHERE cafe_id=c),'[]'),'receipts',coalesce((SELECT jsonb_agg(to_jsonb(r)-'cafe_id') FROM public.erp_purchase_receipts r WHERE cafe_id=c),'[]'),'allocations',coalesce((SELECT jsonb_agg(to_jsonb(a)-'cafe_id') FROM public.erp_purchase_allocations a WHERE cafe_id=c),'[]'),'settings',erp_purchase_private.settings(c),'units',units,'costCenters',centers,
 'inventoryDocuments',inventorydocs,'itemDefaults',defaults,'categories',categories,'blockedItems',coalesce((SELECT jsonb_agg(id) FROM public.bf_items WHERE cafe_id=c AND erp_purchase_private.item_blocked(c,id,erp_purchase_private.settings(c))),'[]'),'statements',coalesce((SELECT jsonb_agg(x ORDER BY x.date,x.number) FROM(SELECT j.party_id AS "supplierId",d.id AS "documentId",d.number,d.created_at AS date,d.kind,d.note,sum(j.debit) debit,sum(j.credit) credit FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id JOIN public.bf_documents d ON d.cafe_id=j.cafe_id AND d.id=j.document_id JOIN public.bf_parties b ON b.cafe_id=j.cafe_id AND b.id=j.party_id WHERE j.cafe_id=c AND b.kind='supplier' AND a.kind IN('payable','receivable') GROUP BY j.party_id,d.id,d.number,d.created_at,d.kind,d.note)x),'[]'),
 'events',coalesce((SELECT jsonb_agg(x) FROM(SELECT id,record_id AS "recordId",action,at,payload->>'note' AS note FROM public.erp_purchase_events WHERE cafe_id=c ORDER BY at DESC LIMIT 500)x),'[]'),
 'canCreate',erp_purchase_private.allowed(c,'create'),'canUpdate',erp_purchase_private.allowed(c,'update'),'canDelete',erp_purchase_private.allowed(c,'delete'),'canApprove',erp_purchase_private.allowed(c,'approve'),'canConfigure',erp_purchase_private.allowed(c,'settings'),'canFiles',erp_purchase_private.allowed(c,'files'));
END$$;
CREATE TABLE public.erp_purchase_line_centers(cafe_id uuid NOT NULL,document_id uuid NOT NULL,line_id uuid PRIMARY KEY,cost_center_id uuid NOT NULL,amount numeric(18,2) NOT NULL,FOREIGN KEY(cafe_id,document_id) REFERENCES public.bf_documents(cafe_id,id),FOREIGN KEY(line_id) REFERENCES public.bf_document_lines(id));
CREATE INDEX erp_purchase_line_centers_scope ON public.erp_purchase_line_centers(cafe_id,cost_center_id,document_id);
ALTER TABLE public.erp_purchase_line_centers ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.erp_purchase_line_centers FROM PUBLIC,anon,authenticated,service_role;
DO $$BEGIN IF to_regclass('public.erp_cost_centers') IS NOT NULL THEN ALTER TABLE public.erp_purchase_line_centers ADD FOREIGN KEY(cafe_id,cost_center_id) REFERENCES public.erp_cost_centers(cafe_id,id);END IF;END$$;
CREATE FUNCTION erp_purchase_private.line_metadata() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$DECLARE r public.erp_purchase_documents%ROWTYPE;l jsonb;center uuid;valid boolean;cfg jsonb;BEGIN
 IF NEW.finance_id IS NULL OR OLD.finance_id IS NOT NULL THEN RETURN NEW;END IF;cfg:=erp_purchase_private.settings(NEW.cafe_id);
 FOR l IN SELECT value FROM jsonb_array_elements(NEW.payload->'lines') LOOP center:=nullif(l->>'costCenterId','')::uuid;
  IF center IS NOT NULL THEN IF to_regclass('public.erp_cost_centers') IS NULL THEN RAISE EXCEPTION 'مراكز التكلفة غير متاحة';END IF;EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.erp_cost_centers WHERE cafe_id=$1 AND id=$2 AND active AND NOT is_group)' INTO valid USING NEW.cafe_id,center;IF NOT valid THEN RAISE EXCEPTION 'مركز التكلفة غير متاح';END IF;
   INSERT INTO public.erp_purchase_line_centers(cafe_id,document_id,line_id,cost_center_id,amount) SELECT NEW.cafe_id,NEW.finance_id,id,center,net FROM public.bf_document_lines WHERE cafe_id=NEW.cafe_id AND document_id=NEW.finance_id AND id=(l->>'id')::uuid;
  END IF;
  IF(cfg->>'updateItemPrices')::boolean AND to_regclass('public.erp_inventory_items') IS NOT NULL THEN EXECUTE 'INSERT INTO public.erp_inventory_items(cafe_id,item_id,payload) VALUES($1,$2,jsonb_build_object(''buyPrice'',$3,''buyUnitName'',$4)) ON CONFLICT(cafe_id,item_id) DO UPDATE SET payload=erp_inventory_items.payload||excluded.payload,revision=erp_inventory_items.revision+1' USING NEW.cafe_id,(l->>'itemId')::uuid,round((l->>'price')::numeric*(NEW.payload->>'exchangeRate')::numeric,2),l->>'unit';END IF;
 END LOOP;RETURN NEW;
END$$;
CREATE TRIGGER erp_purchase_line_metadata AFTER UPDATE OF finance_id ON public.erp_purchase_documents FOR EACH ROW EXECUTE FUNCTION erp_purchase_private.line_metadata();
CREATE FUNCTION public.erp_purchase_cost_report(p_cafe_id uuid,p_from date,p_to date,p_center uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN
 PERFORM erp_purchase_private.authorize(p_cafe_id,'read');IF p_from IS NULL OR p_to IS NULL OR p_to<p_from OR p_to-p_from>3660 THEN RAISE EXCEPTION 'فترة التقرير غير صالحة';END IF;
 RETURN jsonb_build_object('classification','purchase_cost','currency','SAR','rows',coalesce((WITH source AS(SELECT a.cost_center_id,coalesce(sum(a.amount) FILTER(WHERE l.item_id IS NOT NULL),0) capitalized,coalesce(sum(a.amount) FILTER(WHERE l.item_id IS NULL),0) expensed,0::numeric returned FROM public.erp_purchase_line_centers a JOIN public.bf_documents d ON d.cafe_id=a.cafe_id AND d.id=a.document_id JOIN public.bf_document_lines l ON l.cafe_id=a.cafe_id AND l.id=a.line_id WHERE a.cafe_id=p_cafe_id AND(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN p_from AND p_to GROUP BY a.cost_center_id
 UNION ALL SELECT a.cost_center_id,0,0,sum(l.net) FROM public.erp_purchase_line_centers a JOIN public.bf_document_lines l ON l.cafe_id=a.cafe_id AND l.reference_line_id=a.line_id JOIN public.bf_documents d ON d.cafe_id=l.cafe_id AND d.id=l.document_id AND d.kind='refund' WHERE a.cafe_id=p_cafe_id AND(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN p_from AND p_to GROUP BY a.cost_center_id
 UNION ALL SELECT a.cost_center_id,0,0,sum(n.net) FROM public.erp_purchase_line_centers a JOIN public.erp_purchase_debits n ON n.cafe_id=a.cafe_id AND n.line_id=a.line_id JOIN public.bf_documents d ON d.cafe_id=n.cafe_id AND d.id=n.document_id WHERE a.cafe_id=p_cafe_id AND(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN p_from AND p_to GROUP BY a.cost_center_id)
 SELECT jsonb_agg(x) FROM(SELECT cost_center_id AS "centerId",sum(capitalized) AS "capitalizedPurchases",sum(expensed) AS "expensedPurchases",sum(capitalized+expensed) AS "grossPurchases",sum(returned) AS "returnedPurchases",sum(capitalized+expensed-returned) AS "netPurchases" FROM source WHERE p_center IS NULL OR cost_center_id=p_center GROUP BY cost_center_id)x),'[]'));
END$$;
CREATE FUNCTION erp_purchase_private.protect_posted() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN
 IF EXISTS(SELECT 1 FROM public.erp_purchase_documents WHERE cafe_id=OLD.cafe_id AND finance_id=OLD.id) AND(TG_OP='DELETE' OR ROW(NEW.cafe_id,NEW.kind,NEW.party_id,NEW.warehouse_id,NEW.total,NEW.paid,NEW.tax,NEW.created_at) IS DISTINCT FROM ROW(OLD.cafe_id,OLD.kind,OLD.party_id,OLD.warehouse_id,OLD.total,OLD.paid,OLD.tax,OLD.created_at)) THEN RAISE EXCEPTION 'فاتورة المشتريات المرحّلة تصحح بمرتجع أو إشعار مدين';END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END$$;
CREATE TRIGGER erp_purchase_posted_guard BEFORE UPDATE OR DELETE ON public.bf_documents FOR EACH ROW EXECUTE FUNCTION erp_purchase_private.protect_posted();
CREATE FUNCTION erp_purchase_private.guard_cost_links() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN
 IF TG_TABLE_NAME='erp_cost_centers' THEN IF NEW.is_group AND EXISTS(SELECT 1 FROM public.erp_purchase_line_centers WHERE cafe_id=OLD.cafe_id AND cost_center_id=OLD.id) THEN RAISE EXCEPTION 'مركز التكلفة مستخدم في المشتريات ولا يمكن تحويله إلى رئيسي';END IF;
 ELSE IF NEW.reversal_document_id IS NOT NULL AND OLD.reversal_document_id IS NULL AND EXISTS(SELECT 1 FROM public.erp_purchase_allocations WHERE cafe_id=OLD.cafe_id AND expense_document_id=OLD.document_id) THEN RAISE EXCEPTION 'مصروف القيد موزع على المشتريات ولا يمكن عكسه مباشرة';END IF;END IF;RETURN NEW;
END$$;
DO $$BEGIN IF to_regclass('public.erp_cost_centers') IS NOT NULL THEN CREATE TRIGGER erp_purchase_center_guard BEFORE UPDATE ON public.erp_cost_centers FOR EACH ROW EXECUTE FUNCTION erp_purchase_private.guard_cost_links();END IF;IF to_regclass('public.bf_gl_drafts') IS NOT NULL THEN CREATE TRIGGER erp_purchase_expense_guard BEFORE UPDATE ON public.bf_gl_drafts FOR EACH ROW EXECUTE FUNCTION erp_purchase_private.guard_cost_links();END IF;END$$;
CREATE FUNCTION erp_purchase_private.guard_settlement() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN IF NEW.kind='settlement' AND EXISTS(SELECT 1 FROM public.erp_purchase_documents WHERE cafe_id=NEW.cafe_id AND finance_id=NEW.reference_id) THEN PERFORM erp_purchase_private.authorize(NEW.cafe_id,'approve');END IF;RETURN NEW;END$$;
CREATE TRIGGER erp_purchase_settlement_scope BEFORE INSERT ON public.bf_documents FOR EACH ROW EXECUTE FUNCTION erp_purchase_private.guard_settlement();
ALTER FUNCTION erp_file_private.assert_record(uuid,text,uuid,boolean) RENAME TO assert_record_before_purchases;
CREATE FUNCTION erp_file_private.assert_record(p_cafe uuid,p_type text,p_record uuid,p_write boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$BEGIN
 IF p_type NOT IN('purchase_document','supplier_profile') THEN PERFORM erp_file_private.assert_record_before_purchases(p_cafe,p_type,p_record,p_write);RETURN;END IF;
 PERFORM erp_purchase_private.authorize(p_cafe,CASE WHEN p_write THEN 'files' ELSE 'read' END);
 IF p_type='purchase_document' AND NOT EXISTS(SELECT 1 FROM public.erp_purchase_documents WHERE cafe_id=p_cafe AND id=p_record) OR p_type='supplier_profile' AND NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe AND id=p_record AND kind='supplier') THEN RAISE EXCEPTION 'سجل المرفقات غير متاح' USING ERRCODE='42501';END IF;
END$$;
ALTER FUNCTION erp_access_private.file_domain(text) RENAME TO file_domain_before_purchases;
CREATE FUNCTION erp_access_private.file_domain(p_type text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$SELECT CASE WHEN p_type IN('purchase_document','supplier_profile') THEN 'purchases' ELSE erp_access_private.file_domain_before_purchases(p_type) END$$;
CREATE TRIGGER erp_purchase_files_guard BEFORE DELETE ON public.erp_purchase_documents FOR EACH ROW EXECUTE FUNCTION erp_file_private.prevent_orphans('purchase_document');
CREATE TRIGGER erp_supplier_files_guard BEFORE DELETE ON public.bf_parties FOR EACH ROW EXECUTE FUNCTION erp_file_private.prevent_orphans('supplier_profile');
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA erp_purchase_private FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION brand_finance_private.refund_lines(uuid,uuid,boolean),brand_finance_private.refund_lines_before_purchase_debits(uuid,uuid,boolean),erp_file_private.assert_record(uuid,text,uuid,boolean),erp_file_private.assert_record_before_purchases(uuid,text,uuid,boolean),erp_access_private.file_domain(text),erp_access_private.file_domain_before_purchases(text) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION brand_finance_private.post_refund(uuid,jsonb,uuid),brand_finance_private.post_refund_before_purchase_services(uuid,jsonb,uuid) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.erp_purchases_read(uuid),public.erp_purchases_write(uuid,text,jsonb,uuid),public.erp_purchase_cost_report(uuid,date,date,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.erp_purchases_read(uuid),public.erp_purchases_write(uuid,text,jsonb,uuid),public.erp_purchase_cost_report(uuid,date,date,uuid) TO authenticated;
NOTIFY pgrst,'reload schema';
COMMIT;
